      equ	12	DC.B 1	bULShadow      equ	13	DC.B 0	scan           equ	14	DC.B 0	bXInfoX        equ	16	DCB.B 8,0	reserved*prJob          equ	 80       SubRecord* TPrJob subrecord length = 20 bytes	DC.W 1	iFstPage       equ	0	DC.W 999	iLstPage       equ	2	DC.W 1	iCopies        equ	4	DC.B 1	bjDocLoop      equ	6	DC.B 1	fFromUsr       equ	7	DC.L 0	pIdleProc      equ	8	DC.L 0	pFileName      equ	12	DC.W 0	iFileVol       equ	16	DC.B 0	bFileVers      equ	18	DC.B 0	bJobX          equ	19*printx         equ	 100      Array[1..19] of integer (38 bytes)	DC.W 0	DC.W 25	DC.W 400	DC.L 0	Nil	DC.W 0	; should be a total	of 20 integers	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	DC.W 0	EXPORT VResVRes	DC.W 36	DC.W 54	DC.W 72	EXPORT hReshRes	DC.W 40	DC.W 80	EXPORT VMarginVMargin	DC.W 18	DC.W 36	DC.W 54	DC.W 0	EXPORT HMarginHMargin	DC.W 18	DC.W 29	DC.W 21	DC.W 0	EXPORT PaperVsizePaperVsize	DC.W 792	DC.W 1008	DC.W 842	DC.W 709	EXPORT PaperHsizePaperHsize	DC.W 612	DC.W 612	DC.W 596	DC.W 499	EXPORT pagesizeselectionpagesizeselection	DC.W 1320	DC.W 1680	DC.W 1403	DC.W 1212	ENDP;              copy	   PostScript.Str******************************************************************* PostScript strings** Current Rev. Jan 19, 1988******************************************************************	EXPORT PostScriptStrPostScriptStr	PROC	EXPORT TrueStr	EXPORT FalseStr	EXPORT QMark	EXPORT SpaceChar	EXPORT Slash	EXPORT OpenBracket	EXPORT CloseBracket	EXPORT OpenCurly	EXPORT CloseCurly	EXPORT OpenHex	EXPORT CloseHex	EXPORT StartString	EXPORT EndString	EXPORT SemiColonTrueStr	str ' T 'FalseStr	str ' F 'QMark	str '?'SpaceChar	str ' 'Slash	str '/'OpenBracket	str '['CloseBracket	str ']'OpenCurly	str '{'CloseCurly	str '}'OpenHex	str '<'CloseHex	str '>'SemiColon	str ';'StartString	str '('EndString	str ')'	EXPORT returnreturn	DC.B 1	DC.B $0