           _TickCount   ; get starting tick count;              pla;              sta timer    ; keep low word;              pla	    ; discard high word	lda fPSFile	; are we writing to file?	beq Retry	; nope, go open connection to LW;-----------------------------------------------------------;; PostScript output file name format: PostScript.GSxx, where xx are numbers from 00 to 99;	stz Number	; start off with 00TryAgain	PushWord Number	pushlong #NumberStr	PushWord #2	_Int2Hex	; convert to ASCII	bcc @1	brl Error@1	ldx PSFileName	lda NumberStr	; two byte string	sta PSFileName,x	; replace the last two characters	_CreateGS CreateGSParams ; create the file	bcc GoOn	cmp #DupPathName	beq @2	brl Error@2	inc Number	; try next increment	bra TryAgainGoOn	_OpenGS OpenGSParams ; and open it	bcc @1	brl Error@1	lda OpenID	; update the useful IDs	sta WriteID	sta CloseID	stz writelength	brl ExitRetry	stz ReadingDone	; ensures that read buffer is not	jsr GetStatus	; dealt with at this time 4/27/88	lda StatusError	; if an error on status, we've got problems	bne UserAbort	; with the printer	stz OpenDone	pushlong #CompleteOpen	pushlong #0	_PrDevOpenLoopOpen	lda Opendone	; is open complete?	bmi Opened	jsl MyIdleProc	lda iPrErr	; don't bother waiting till connection	bne UserAbort	; is opened if user	cancels	jsr GetStatus	lda StatusError	; if an error on status, we've got problems	bne UserAbort	; with the printer	jsr ShowStatus	bra LoopOpen	; sit and wait;----------------------------------------------------------------;; Next section commented out till new AppleTalk code with PAPOpen; bug fix is available.;;----------------------------------------------------------------;; LaserWriter does not respond while it	is in a warm up cycle.; We cannot always tell if the LaserWriter is not on the network,; not turned on or has just been turned	on and is warming up.; Experiments have shown that the magic	number for warming up is; about 2 minutes. So we check the tick	count each time we get a; NameNotFound error and keep trying for 2 minutes from the	time; of the first attempt.;;              lda OpenError    ; get error from open;              beq OpenOK   ; no problem opening;              cmp #NameNotFound    ; oops, can't find LaserWriter by name;              bne UserAbort    ; do no	more if other errors occur;              PushLong #0;              _TickCount;              pla;              plx	    ; again, get rid of high word;              sec;              sbc timer    ; check against starting count;              cmp #3600*2  ; 2 minutes	passed?;              bge LWNotThere   ; yep, guess LW is not available;              bra Retry;LWNotThere     lda	OpenError;              bra UserAbortOpened;--------------------------------------------------------------------;; Get rid of the next two lines when we	have the new Appletalk code.;	lda OpenError	; get error from open	bne UserAbort	; do no more if error occursOpenOK	lda NoShowMessage	; True if PrPixelMap is calling	bne NoShow	; this routine	dec ShowStatusFlag	; enable status to be shown	jsr ShowStatus	; display PAPOpen statusNoShow	stz writelength	; Nothing to write yet;-----------------------------------------------------------------------;; Issues a PAPRead now so that there will be one pending when we begin; the session.;	stz ReadingDone	stz ReadingLength	PushWord #0	; space for actual length	pushlong #MyCompletion	PushWord #ATFlowQuantum	pushlong #ReadBuffer	_PrDevAsyncRead	pla	; this value is invalid at this		; point in time since this is an		; async read call;; There should not be any read errors until read is completed.;Exit	lda #0ErrorUserAbort	cmp #1	rts	EXPORT OpenDoneOpenDone	DS.B 2	; flag indicating open is completedOpenError	DS.B 2	; error returned from PAPOpen callTimer	DS.B 2	; tick count of first open attemptNumber	DS.B 2	; number for appending to end of PS output fileNumberStr	DC.B $30,$30	; start with 00;---------------------------------------------------------------;; Completion routine for PAPOpen which sets the done flag and; saves error returned.;	EXPORT CompleteOpenCompleteOpen	sta >OpenError	lda #True	sta >OpenDone	rtl	ENDP******************************************************************* Closes PAP connections to the LaserWriter******************************************************************	EXPORT CloseLaserCloseLaser	PROC	lda fPSFile	; are we writing to file?	beq CloseLW	; nope, go close connection to LW	_CloseGS CloseGSParams ; close the PostScript file	rtsCloseLW	_PrDevClose	rts	ENDP******************************************************************* Reads the buffer with data from the LaserWriter******************************************************************	EXPORT ReadLaserReadLaser	PROCLoopRead	lda ReadingDone	bpl LoopRead	lda ReadError	; check error	bne ExitRead	; exit now if there	is one;----------------------------------------------------------------;; Moves the data returned in the read buffer into a local buffer; since the read buffer will be destroyed when the next read is; issued.;	pushlong #ReadBuffer	pushlong #LocalBuffer	PushWord #0	; high byte of long	word is always 0	PushWord ReadingLength ; since the length is 512 max	_BlockMove	lda ReadingLength	sta LocalBufSize	; set up this variable for use later;---------------------------------------------------------------------;; Issue another read, so there will always be one pending.;	stz ReadingDone	stz ReadingLength	PushWord #0	; space for actual length	pushlong #MyCompletion	PushWord #ATFlowQuantum	pushlong #ReadBuffer	_PrDevAsyncRead	pla	; this value is invalid at this		; point in time since this is an		; async read call	lda #0ExitRead	cmp #1	rts;--------------------------------------------------------------;; Completion routine for PAPRead which saves error returned; and sets done flag;	EXPORT MyCompletionMyCompletion	sta >ReadError	txa	sta >ReadingLength	; actual length read	tya	sta >EndofRead	; true if nonzero	lda #True	sta >ReadingDone	rtlReadError	DS.B 2	EXPORT ReadingDoneReadingDone	DS.B 2	ENDP******************************************************************* Writes the contents of the buffer to the LaserWriter******************************************************************	EXPORT WriteLaserWriteLaser	PROC	lda iPrErr	beq GoOn	; no problems	brl ExitGoOn	lda fPSFile	; are we writing to file?	beq Continue	; nope, go deal with LW	lda WriteLength	sta WriteLen	; update value in param block	_WriteGS WriteGSParams	stz writelength	lda #0	bra ExitContinue	stz WriteDone	pushlong #CompleteWrite	pushlong #WriteBuffer	Pushword WriteLength	_PrDevWrite	jsr GetStatus	; gathers status	lda StatusError	; if an error on status, we've got problems	bne Exit	; with the printer	lda NoShowMessage	bne DontShow	jsr ShowStatusDontShow	stz writelength	; reinits buffer content size to 0LoopWrite		;	jsr GetStatus	; gathers status	lda StatusError	; if an error on status, we've got problems	bne Exit	; with the printer	jsl MyIdleProc	lda iPrErr	; Don't bother waiting till write	bne Exit	; is done if user cancels	lda WriteDone	bpl LoopWrite	lda WriteErrorExit	cmp #1	rtsWriteDone	DS.B 2WriteError	DS.B 2;--------------------------------------------------------------;; Completion routine for PAPWrite which	saves error returned; and sets done flag;	EXPORT CompleteWriteCompleteWrite	sta >WriteError	lda #True	sta >WriteDone	rtl	ENDP******************************************************************* Asks the status of the LaserWriter, at 5 second intervals******************************************************************	EXPORT StatusLaserStatusLaser	PROC;-----------------------------------------------------------;; This chunk of code is moved from WriteLaser 4/27/88;CkPrinterErr	lda ReadingDone	bpl Continue	lda ReadingLength	pha	jsr ReadLaser*** added 25-Mar-93 DAL to nuke an infinite loop.  If our session times out we start getting***   error $0806 from ReadLaser, but we didn't care!	bcc @continue	pla	bra ExitStatus@continue*** end 25-Mar-93	pla	beq Continue	dec a	; last character is a control char		; which we do not want shown	tay	; set up Y as the length of string	tax	; move to x for indexing	lda NoShowMessage	bne CkPrinterErr;----------------------------------------------------------------------;; Copy the string from the buffer into local area.;	sep #$30	; go into 8 bit mode	longa offLoop	lda LocalBuffer,x	sta String+1,x	; save byte 0 for carriage return	dex	bpl Loop	lda #CReturn	; pad the string with carriage	sta string	; return	longa on	; get back to 16 bit mode	rep #$30	lda #String	; go display the string	ldx #^String	iny	; y already has the length but		; need to add one due to padding	jsr ShowProgress	bra CkPrinterErr	; see if any other errors		; occurred in the meanwhile;; End of code moved;Continue	pha	pha	; get tick count	_TickCount	plx	pla	cmp NewInterval+2	; check if high word is changed	beq testlower	; no, go check low word	blt ExitStatus	; otherwise, exittestLower	txa	; is low word greater than last look	cmp NewInterval	blt ExitStatus	pha	pha	; yep, get tick count	_TickCount	pla	clc	adc #60*5	; add 5 seconds for	the next time	sta NewInterval	pla	adc #0	sta NewInterval+2	pushlong #StatusBuffer ; issue a PAPstatus	_PrDevStatus	sta StatusError	clc	; carry is cleared if status issued	rtsExitStatus	sec	; carry is set if no status call	rts	EXPORT NewIntervalNewInterval	DS.B 4	EXPORT StringString	DS.B 100	ENDP;                copy    BadReduce	EXPORT BadReduceBadReduce	PROC	pha	pha	_GetPort	lda badreduRect+6	sec	sbc badreduRect+2	sta StyleWidth	pha	_GetMasterSCB	pla	and #$0080	beq loc320	lda #640	bne loc640loc320	lda #320loc640	sec	sbc StyleWidth	lsr a	sta badreduRect+2	clc	adc StyleWidth	sta badreduRect+6	PushLong #0	pushlong #badreduRect	Pushword #1	PushLong #0	_NewModalDialog	pla	sta pBadRedPort	pla	sta pBadRedPort+2	pushlong pBadRedPort	_SetPort	pushlong #0	_SetOrigin	PushLong pBadRedPort	Pushword #1	OK	pushlong #BPOKrect	Pushword #ButtonItem	pushlong #okstr	PushWord #0	PushWord #0	PushLong #0	_NewDItem	pushlong #BrText	PushWord BrTextLength	pushlong #BPTextRect	PushWord #0	_LETextBoxloopModal	PushWord #0	PushLong #0	_ModalDialog	pla	beq loopModal	cmp #2	bge loopModal	asl a	tax	jmp (Action-2,x)Action	DC.W C_OkEvent	;1C_OkEvent	pushlong pBadRedPort	_CloseDialog	_SetPort	rts	ENDP;                Copy    InfoDialogs*******************************                            ** InfoDialogs	         **                            **    Last Rev: Jun 22, 1987  **                            ************************************************************************************************** CloseInfo**    Closes the status window******************************************************************	EXPORT CloseInfoCloseInfo	PROC	PushLong infoDPort	_CloseWindow	rts	ENDP******************************************************************* OpenInfoPrinting**    Puts a window to display status of	the print job******************************************************************	EXPORT OpenInfoPrintingOpenInfoPrinting	PROC	lda SCBValue	; find out mode	and #$0080	beq loc320	; 320 mode	lda infowidth640	; 640 mode	sta StyleWidth	; use 640 size window	lda #640	bne loc640loc320	lda infowidth320	; use 320 size window	sta StyleWidth	lda #320loc640	sec	; fiqure out the x positions	sbc StyleWidth	; of the upper and lower edges	lsr a	; of the info rectangle	sta InfoRect+2	clc	adc StyleWidth	sta InfoRect+6	stz NoShowMessage	; allow message to be shown	PushLong #0	pushlong #InfoWindow	_NewWindow	; creat a new window	pla	sta infoDPort	pla	sta infoDPort+2	lda fPSFile	beq Normal	lda #CreatePSStr+1	ldx #^CreatePSStr+1	ldy CreatePSStr	jsr ShowProgress	bra byeNormal	lda #InfoStrPrep+1	; address of string	to display	ldx #^InfoStrPrep+1	ldy InfoStrPrep	jsr ShowProgressBye	rts	ENDP******************************************************************* GetStatus**    Gets the status of the printer.******************************************************************	EXPORT GetStatusGetStatus	PROC*The following two lines were commented out before 10/23/90.  Why?  Apparently causes problems with*reading in the font list during PrOpenDoc, so these two lines have been activated again.  At*the present time it does not seem that this affects anything else.	lda allowstatus	; if status not allowed	bne ExitGet	; don't do statuslaser (which does a papread)	jsr StatusLaser	; go see if time to	issue status calls	bcs ExitGet	; if no status call	made, leave		; background note: StatusLaser always does a papread,		; and then also does a papstatus every 5 seconds	dec ShowStatusFlag	; enable showing of	statusExitGet	rts	ENDP******************************************************************* ShowStatus**    Displays status of the printer.******************************************************************	EXPORT ShowStatusShowStatus	PROC	EXPORT ShowProgress	ldy ShowStatusFlag	beq ExitStatus	stz ShowStatusFlag;-----------------------------------------------------------;; Bytes 0 - 3 of the buffer contains AppleTalk stuff that we don't; need. The actual status string begins at byte 4 with a length;	ldy StatusBuffer+4	; get the length of the buffer	tyx	; set up loop counter for below;	iny	; and bump by one due to padding;-----------------------------------------------------------;; Switch modes and copy the status string into local area;;	sep #$0030	; go into 8 bit mode	longa offLoop	lda StatusBuffer+5,x	sta String,x	; save byte 0 for carriage return	dex	bpl Loop;	lda #CReturn	; pad the string with carriage;	sta string	; return	longa on	; get back to 16 bit mode	rep #$0030	lda #String	; go display the string	ldx #^StringShowProgress	sta StringAddr	; store address in local variable	stx StringAddr+2	sty textLeng	PushLong #0	; otherwise display	it	_GetPort	; save current port	ptr on stack	PushLong infoDPort	_SetPort	; set our port current	PushLong StringAddr	; address of the string	lda textleng	; length of the text	and #$00FF	; lo byte only	pha	lda SCBValue	; check the mode we are in	and #$0080	beq IsMode320	pushlong #InfoRect640	; use 640 mode rectangle	bra GoOnIsMode320	pushlong #InfoRect320	; use 320 mode rectangleGoOn	lda #0	pha	; left justification	_LETextBox2	_SetPort	; put back old portExitStatus	rtsStringAddr	DS.B 4textLeng	DS.B 2	ENDP;                copy    ErrorCalls	EXPORT PrErrorPrError	PROC	DefineStack* iPrErr* parameters:* return error valueError_DPage	word 0Error_BReg	byte 0Error_rtl1	block 3Error_rtl2	block 3Error_Value	word 0	phd	tcd	phb	phk	plb	lda iPrErr	sta Error_Value,s	lda #0	plb	pld	brl exit0	EXPORT PrSetErrorPrSetError* parameters:* error value	DSect 1SetError_DPage	word 0SetError_BReg	byte 0SetError_rtl1	block 3SetError_rtl2	block 3SetError_value	word 0	phd	tcd	phb	phk	plb	lda SetError_value,s	sta iPrErr	lda #0	plb	pld	brl exit2	ENDP;                Copy    DynamicExits	EXPORT DynamicExitsDynamicExits	PROC* in a Dynamic exit	we need to save 2 RTLs	EXPORT Exit12Exit12	tax	lda 5,s	sta 17,s	lda 3,s	sta 15,s	lda 1,s	sta 13,s	tsc	clc	adc #12	tcs	txa	bra Exit0	EXPORT Exit10Exit10	tax	lda 5,s	sta 15,s	lda 3,s	sta 13,s	lda 1,s	sta 11,s	pla	pla	pla	pla	pla	txa	brl exit0	EXPORT Exit8Exit8	tax 	;Standard 8 bytes input exit	lda 5,s	sta 13,s	lda 3,s	sta 11,s	lda 1,s	sta 9,s	pla	pla	pla	pla	txa	brl Exit0	EXPORT Exit4Exit4	tax	;Standard 4 bytes input exit	lda 5,s	sta 9,s	lda 3,s	sta 7,s	lda 1,s	sta 5,s	pla	pla	txa	brl Exit0	EXPORT Exit2Exit2	tax	;Standard 2 bytes input exit	lda 5,s	sta 7,s	lda 3,s	sta 5,s	lda 1,s	sta 3,s	pla	txa	EXPORT Exit0Exit0	cmp #1	;Standard 0 byte input exit	rtl	ENDP;                copy    PrPicFile******************************                           ** PrPicFile                 **                           ** Current Rev: Mar 02, 1988 **                           ************************************************************************************************* PrPicFile** This call does nothing in the LaserWriter Driver.******************************************************************	EXPORT PrPicFilePrPicFile	PROC	lda #0000	;this will be the normal exit	brl exit12	ENDP******************************************************************* PrPixelMap*              SrcLocPtr      LONG   ptr to source LocInfo*              SrcRectPtr     LONG   ptr to source rect*              ColorFlag      WORD   0 = B/W, else color******************************************************************	EXPORT PrPixelMapPrPixelMap	PROC	DefineStackOrigD	word 0OrigB	byte 0rtl1	block 3rtl2	block 3ColorFlag	word 0SrcRectPtr	long 0SrcLocPtr	long 0	pha	; save value of d	pha	_DevIsItSafe	pla	bne Yes	lda #PortNotOn	sta >iPrErr	plx	brl Exit10Yes	pla;------------------------------------------------------------;; save the registers and set direct page and data bank;	phd	tcd	phb	phk	plb;------------------------------------------------------------;; Get the current port's pointer and leave it on the stack; for restoring just before returning.;	pha	pha	_GetPort;------------------------------------------------------------;; Turn on the watch	cursor.	jsr WaitCursor;------------------------------------------------------------;; Clear the error code and disallow message display.;	stz iPrErr	; zero error	lda #True	sta NoShowMessage;------------------------------------------------------------;; Get source bitmap	information off the	stack into local area;	lda SrcLocPtr+4,s	sta QD_Temp1	; QD_Temp1 has Ptr to SrcLoc	lda SrcLocPtr+2+4,s	sta QD_Temp1+2	ldy #14MoveLoc	lda [QD_Temp1],y	sta LocalLoc,y	dey	dey	bpl MoveLoc	lda QD_Temp1	clc	adc #8	sta LocalBoundsPtr	; this ptr used for	intersection call	lda QD_Temp1+2	adc #0	sta LocalBoundsPtr+2	lda SrcRectPtr+4,s	sta QD_Temp2	; QD_Temp2 is ptr to source rect	lda SrcRectPtr+2+4,s	sta QD_Temp2+2	PushWord #0	; Result	PushLong LocalBoundsPtr	PushLong QD_Temp2	PushLong #LocalRect	; intersected rect goes here	_SectRect	pla	bne ItsOK	brl NoIntersection	; if false, no intersection;------------------------------------------------------------;; Get new handle for print record. This	is necessary because; the values in the	print record are used to set up parameters; for the printer.;ItsOK	lda #TPrintSize	; size of handle	ldx #%1000000000011000 ; attributes	jsr OurGetHandle	bcc @1	sta iPrErr	brl NoIntersection@1	sta PrintRecord	stx PrintRecord+2	PushLong PrintRecord	_PrDefault;------------------------------------------------------------;; Check if the the application gave us a background procedure,; if so, we use it,	otherwise we use PrAbortCheck, which polls; the keyboard for command-period.;	lda hPrint+PrJob+pIdleProc	ora hPrint+PrJob+pIdleProc+2	bne useridle	lda #<PrAbortCheck	sta hPrint+PrJob+pIdleProc	lda #^PrAbortCheck	sta hPrint+PrJob+pIdleProc+2useridle;------------------------------------------------------------;; Open the connection to the LaserWriter and send our PostScript dictionary;	jsr OpenLaser	; opens connection	bcc LaserOpened	; open successful?	cmp #iPrAbort	beq @1	lda #PAPConnNotOpen	; Nope, set error	sta iPrErr@1	brl ExitPixelMap	; and quitLaserOpened	lda fPSFile	; non zero means writing to a file	beq @NoFile	lda #1	sta LWType	; if writing to a file, assume LW Plus or II	bra GotNames	; no need to set up tables@NoFile	jsr SetUpNameTables	bcc GotNames	sta iPrErr	brl ExitPixelMap1	; error, most likely memory problemsGotNames;-----------------------------------------------------------;; Send PostScript header comments;	pushlong #JobTitleComment	jsr AddstrToWBuff	PushLong #0	_PMGetDocName	; result is left on stack for	jsr AddStrToWBuff	; this call	pushlong #ForUserComment	jsr AddstrToWBuff	PushLong #0	; NIL may be important! (18-Feb-93 DAL)	_PMGetUserName	; get pointer and leave it on	jsr AddStrToWBuff	; stack for this call	pushlong #HeaderComment ; the rest of the stuff we don't deal with now	jsr AddstrToWBuff	jsr WriteLaser	; send everything in buffer now	jsl SendThePrep	bcc GoUnload	; no error	lda iPrErr	; check if error is	a user cancel	cmp #iPrAbort	beq GoUnload	; yep	lda #PAPReadWriteErr ; otherwise it's a PAP error	sta iPrErrGoUnload	pha	pha	pha	; space for results	phx	phy	_UnloadSeg	; unload the dynamic segment	plx	plx	plx	; ignore results	lda iPrErr	beq GoOn	brl ExitPixelMap1GoOn	pushlong #EndPrologComment	jsr AddStrToWBuff;------------------------------------------------------------;; Get a handle for a grafport.;	lda #PortSize	; size of handle	ldx #%1000000000011000 ; attributes	jsr OurGetHandle	bcc OK2	sta iPrErr	brl ExitPixelMap1OK2	sta QD_Temp1	stx QD_Temp1+2	lda [QD_Temp1]	sta PZ_pPrPort	ldy #2	lda [QD_Temp1],y	sta PZ_pPrPort+2;------------------------------------------------------------;; Open the grafport.;	pei PZ_pPrPort+2	pei PZ_pPrPort	_OpenPort;------------------------------------------------------------;; Initial variable to indicate pixel has not been defined yet; in PostScript and	set to page 1.;	stz PixelInstalled	lda #01	sta iPageNum;------------------------------------------------------------;; Install our own grafproc for pixel, so we can make QD call; PPToPort and use the pixel code as is.;	pushlong #DefaultProcs ; set up the two tables with	_SetStdProcs	; standard proc pointers	pushlong #ProcsTable	_SetStdProcs	lda #<Pixel-1	; put our pointer into table	sta ProcsTable+$20	lda #^Pixel-1	sta ProcsTable+$22	pushlong #ProcsTable	; install it	_SetGrafProcs;------------------------------------------------------------;; Send header and other vital information at start of a; document.;	jsr OpenDocHeader;-----------------------------------------------------------;; Send stuff for the page;	pushlong #PageComment	; page comment	jsr AddStrToWBuff	lda iPageNum	jsr addacc	pushlong #Return	jsr AddStrToWBuff	pushlong #OpenPage	jsr AddStrToWBuff;------------------------------------------------------------;; Make the PPToPort	call;	pushlong #LocalLoc	pushlong #LocalRect	lda #0	pha	pha	pha	_PPToPort;-----------------------------------------------------------;; Time to close the	page (send PostScript ShowPage operator);	pushlong #ClosePage	jsr AddStrToWBuff;------------------------------------------------------------;; and close the document: send trailer information and close; the connection to	the LaserWriter.;	pushlong #TrailerComment	jsr AddStrToWBuff	pushlong #CloseDoc	jsr AddStrToWBuff	pushlong #PagesComment	jsr AddStrToWBuff	lda iPageNum	jsr addacc	pushlong #EOFComment	jsr AddStrToWBuff	jsr WriteLaser	; write the last of	the stuff in		; the buffer;------------------------------------------------------------;; Close the grafport.;	pei PZ_pPrPort+2	pei PZ_pPrPort	_ClosePort;------------------------------------------------------------;; Get rid of the memory we allocated for grafport and print; record and font list buffers.;	pha	; first find the handle to	pha	; memory that port is in.	pei PZ_pPrPort+2	pei PZ_pPrPort	_FindHandle	_DisposeHandle	; then dispose it.ExitPixelMap1	lda fPSFile	; are we writing to file?	bne ExitPixelMap	lda RawBuffHdl+2	; yep, skip the disposal since the following	pha	; buffers were never allocated	lda RawBuffHdl	pha	_DisposeHandle	pha	pha	lda LengTabPtr+2	pha	lda LengTabPtr	pha	_FindHandle	_DisposeHandle	pha	pha	lda OffTabPtr+2	pha	lda OffTabPtr	pha	_FindHandle	_DisposeHandleExitPixelMap	PushLong PrintRecord	_DisposeHandle;------------------------------------------------------------;; Close the connection to the LaserWriter.;	jsr CloseLaser;------------------------------------------------------------;; Turn off the watch cursor.	jsr RestoreCursor;------------------------------------------------------------;; Restore the user's last current port, the pointer to it was; left on the stack	at the beginning of	this routine.;	_SetPort;------------------------------------------------------------;; We are done.;	lda iPrErrNoIntersection	plb	pld	brl Exit10PrintRecord	DS.B 4LocalBoundsPtr	DS.B 4LocalLoc	DS.B 16LocalRect	DS.B 8	ENDP;                copy    PrChanged	EXPORT PrChangedPrChanged	PROC	phd	phb	phk	plb	tcd	pushlong #Printer_Name	_PrDevPrChanged	plb	pld	brl exit0	ENDP;                copy    Metrics******************************* Metrics** Current Rev: Aug 17, 1987******************************	EXPORT metricsmetrics	PROC	DefineStack;------------------------------------------------------------------------;; Returns version #	of currently installed driver;	EXPORT PrDrvrVerPrDrvrVerDVerOrigD	Word 0DVerOrigB	Byte 0DVer_Rtl1	Block 3DVer_Rtl2	Block 3Version	Word 0	phd	tcd	phb	phk	plb	lda #VersionNb	sta Version,s	lda #0	plb	pld	brl exit0;-----------------------------------------------------------;; Returns the printer's type and its characteristics;  type: 0 = undefined;        1 = ImageWriter and ImageWriter II;        2 = ImageWriter