phd	tcd	phb	phk	plb	sta ZeroPage	lda PrStl_hPrint,s	sta PZ_hprint	lda PrStl_hPrint+2,s	sta PZ_hprint+2	pushlong PZ_hprint	_hlock;; call PrValidate to check if printer type is same;	PushWord #0	PushLong PZ_hprint	_PrValidate	plx	bcc MoveOn	brl ErrorExit1	; memory manager error;MoveOn	lda [PZ_hprint]	tax	; store in x temporarily till high	ldy #2	; word is done	lda [PZ_hprint],y	sta PZ_hprint+2	;dereference	stx PZ_hprint	ldy #TPrintsize-2	;pairslooph	lda [PZ_hprint],y	sta hprint,y	dey	dey	bpl slooph	lda #False	ldx #24clrbtn	sta buttonstate,x	dex	dex	bpl clrbtn	lda hprint+prStl+PaperType	cmp #4	blt goodtype	lda #0goodtype	asl a	tax	lda #True	sta buttonstate,x	lda hprint+prStl+Vsizing	cmp #3	blt goodsize	lda #0goodsize	asl a	tax	lda #True	sta buttonstate+2*6,x	lda #f3	;Font Substitution	and hprint+prstl+wdev	bne over5	dec Buttonstate+2*5over5	lda #f2	;smoothing	and hprint+prstl+wdev	bne over4	dec Buttonstate+2*4over4	lda #f1	;portrait	and hprint+prstl+wdev	bne over10	dec Buttonstate+2*10	bra over11over10	dec Buttonstate+2*11over11	lda hprint+prstl+reduced	sta Buttonstate+2*9	jsr styledialog	sta PrStl_result,s	bne okStyle	brl outStyleokStyle* Update PaperType Field	lda Buttonstate+2*9	sta hprint+prstl+reduced	ldx #0	lda buttonstate+2*0	bmi NewPaperSize	inx	lda buttonstate+2*1	bmi NewPaperSize	inx	lda buttonstate+2*2	bmi NewPaperSize	inxNewPaperSize	stx hprint+prStl+PaperType* update the Vsizing Field	ldx #0	lda buttonstate+2*6	bmi normal	inx	lda buttonstate+2*7	bmi normal	inxnormal	stx hprint+prStl+Vsizing* update Font substitution	lda #f3	;Font Substitution	tsb hprint+prstl+wdev	bit buttonstate+2*5	bpl no3	trb hprint+prstl+wdevno3	lda #f2	;Smoothing	tsb hprint+prstl+wdev	bit buttonstate+2*4	bpl no2	trb hprint+prstl+wdevno2	lda #f1	;Portrait	tsb hprint+prstl+wdev	bit buttonstate+2*10	bpl no1	trb hprint+prstl+wdevno1	jsr CiXmetrics	ldy #TPr