********************************************* CiXMetrics** This routine does	a bunch of calculations on page sizes using* the information in Hprint. It puts the newly calculated values* back into Hprint.** To get rPaper+top:*        - (margin x 100 / reduction x Vres ( indexed by Vsize) / 72)*        (VMargin for portrait, HMargin	for landscape)* To get rPaper+left:*        - (margin x 100 / reduction x Hres ( indexed by mode) / 72)*        (HMargin for portrait, VMargin	for landscape)* To get rPaper+bottom:*        papersize x 100 / reduction x Vres ( indexed by Vsize) / 72 + top*        (Vsize for	portrait, Hsize for	landscape)* To get rPaper+right:*        papersize x 100 / reduction x Hres ( indexed by mode) / 72 + left*        (Hsize for	portrait, Vsize for	landscape)** rPage: 0, 0, rPaper+top + rPaper+bottom, rPaper+left + rPaper+right** iHres: indexed by	mode* iVres: indexed by	Vsize******************************************************************	EXPORT CiXmetricsCiXmetrics* 0) assure reduce is within the values	iZoomMin iZoomMax	lda hprint+prstl+reduced	cmp hprint+printx+iZoomMin	bge bigenough	lda hprint+printx+iZoomMin	sta hprint+prstl+reducedbigenough	cmp hprint+printx+iZoomMax	beq smallenough	blt smallenough	lda hprint+printx+iZoomMax	sta hprint+prstl+reducedsmallenough* We need to know:* Landscape (f1)	 { 0=landscape ; 1=Portrait }* PaperType (0,1,2,3) { 0= Us Letter; 1= US Legal; 2= A4 Letter; 3= B5 Letter }* Vsizing (0,1,2)	  { 0= Normal; 1= Compressed; 2= Mac Like }* Resolution (0,1)	  { 0=320 ; 1=640 }* newVmargin: landscape(Vmargin:Hmargin),PaperType mul Vres,VSizing div 72* newHmargin: landscape(Hmargin:Vmargin),PaperType mul Hres,Resolution div 72* NewPaperVsize: landscape(PaperVsize:PaperHsize),PaperType	mul*                Vres,VSizing div 72 - newVmargin* NewPaperHsize: landscape(PaperHsize:PaperVsize),PaperType	mul*                Hres,Resolution div 72	- newHmargin* rPage := 0,0,NewPaperVsize-newVmargin,NewPaperHsize-newHmargin* rPaper := -newVmargin,-newHmargin,NewPaperVsize,NewPaperHsize* 1) get resolution	stz resolution	lda SCBValue	and #$0080	beq r320	inc resolutionr320* 2) Calculate hprint+rPaper+Top	PushLong #0	Result for Divide	PushLong #0	Result for Multiply	PushLong #0	Result for Divide	PushLong #0	Result for Divide	PushLong #0	Result for Multiply	lda hprint+prStl+PaperType	asl a	tax	lda hprint+prstl+wdev	and #f1	bne Land1	lda VMargin,x	bra Port1Land1	Lda HMargin,xPort1	Pha	lda #100	pha	_Multiply	lda #0	pha	lda hprint+prstl+reduced	pha	_LongDivide	pla	plx	plx	plx	pha	lda hprint+prStl+Vsizing	asl a	tax	lda Vres,x	pha	_Multiply	pla	plx	pha	lda #72	pha	_UDivide	pla	plx	eor #True	inc a	sta hprint+rPaper+Top* calculate hprint+rPaper+Left	PushLong #0	Result for Divide	PushLong #0	Result for Multiply	PushLong #0	Result for Divide	PushLong #0	Result for Divide	PushLong #0	Result for Multiply	lda hprint+prStl+PaperType	asl a	tax	lda hprint+prstl+wdev	and #f1	bne Land2	lda HMargin,x	bra Port2Land2	Lda VMargin,xPort2	Pha	lda #100	pha	_Multiply	lda #0	pha	lda hprint+prstl+reduced	pha	_LongDivide	pla	plx	plx	plx	pha	lda resolution	asl a	tax	lda Hres,x	pha	_Multiply	pla	plx	pha	lda #72	pha	_UDivide	pla	plx	eor #True	inc a	sta hprint+rPaper+Left* calculate calculate hprint+rPaper+Bottom	PushLong #0	PushLong #0	Result for Divide	PushLong #0	Result for Multiply	PushLong #0	Result for Divide	PushLong #0	Result for Divide	PushLong #0	Result for Multiply	lda hprint+prStl+PaperType	asl a	tax	lda hprint+prstl+wdev	and #f1	bne Land3	lda PaperVsize,x	bra Port3Land3	Lda PaperHsize,xPort3	Pha	lda #100	pha	_Multiply	lda #0	pha	lda hprint+prstl+reduced	pha	_LongDivide	pla	plx	plx	plx	pha	lda hprint+prStl+Vsizing	asl a	tax	lda Vres,x	pha	_Multiply	lda #0	pha	lda #72	pha	_LongDivide	pla	plx	plx	plx	clc	adc hprin