	phy	phx	_HiliteControl	plx	ply	phy	phx	pushword #0	phy	phx	_HiliteControl	pla	plaDoneJobEsc	cmp #'m'	beq itsM	cmp #'M'	bne doneCmdMkeyitsM	lda evtmods	and #$0100	;command	beq doneCmdMkeyitsCM	lda buttonstate+2*2	;get setting of autofeed button	bne WasAutoIsManWasManIsAuto	dec a	;was manual, setting to auto	sta buttonstate+2*2 ;store $FFFF in autofeed button	stz buttonstate+2*3 ;store $0000 in manfeed button	bra AlterFeedCtlWasAutoIsMan	sta buttonstate+2*3 ;was auto, setting to man; store $FFFF in manfeed button	stz buttonstate+2*2 ;store $0000 in autofeed buttonAlterFeedCtl	lda buttonstate+2*2 ;now update auto/man buttons; get state of auto button	and #1	;turn into 0/1	pha	;save it for a moment on stack	pha	;pass new auto button value	pushlong pscreenport ;pass dialog gport ptr	pushword #5	;pass id of auto button	_SetDItemValue	;redraw auto button control	pla	;restore 0/1 auto button state from stack	eor #1	;flip it	pha	;pass new man button value	pushlong pscreenport ;pass dialog gport ptr	pushword #6	;pass id of man button	_SetDItemValue	;redraw man button control	bra doneJobFilterdoneCmdMkey	cmp #Tab	beq KeyAllowed	cmp #CReturn	beq KeyAllowed	cmp #Delete	beq KeyAllowed	cmp #'0'	blt notallowed	cmp #':'	bge notallowedKeyAllowed	bra doneJobFilternotallowed	lda #-1	sta result,sdoneJobFilter	plb	pld	lda 0,s	sta 12,s	lda 2,s	sta 14,s	pla	pla	pla	pla	pla	pla	rtl	ENDP**************************************************************              			** DocPage      			**              			** Current Rev: Jan 27, 1988       	 	**              			** Revised to use new PostScript - GSPrep       	**              			******************************************************************************************************************************* PrOpenDoc** parameters:     result        returns	ptr to printing grafport*                 UserhPrint    handle to print record*                 pPrPort       ptr to printing grafport, if*                               Nil, it will be allocated****************************************************************	EXPORT PrOpenDocPrOpenDoc	PROC	DefineStackDPage	word 0BReg	byte 0rtl1	block 3rtl2	block 3SpPrPort	long 0UserhPrint	long 0SResult	long 0	pha	; save value of d	pha	_DevIsItSafe	pla	bne Yes	lda #PortNotOn	sta >iPrErr	plx	brl Exit8Yes	pla	phd	tcd	phb	phk	plb	sta ZeroPage	pha	_GetMasterSCB	pla	sta SCBValue	jsr WaitCursor	stz iPrErr	; noErr	stz fPSFile	; printing, not write to file* verify hPrint	lda UserhPrint+2,s 	; get the handle off the stack	pha	lda UserhPrint+2,s	pha	pushlong #hPrint	PushLong #TPrintSize	_HandToPtr	; copy it to our local area;----------------------------------------------------------------------;; Test if correct printer type (1 = ImageWriter, 2 = IW LQ, 3 = LaserWriter,; 4 = Epson) and correct version number.;	lda hPrint+prInfo+idev	cmp #iDevLW	; this is LaserWriter driver	bne WrongType	lda hPrint+iPrVersion ; check if correct version	xba	; swap since hi-lo bytes	cmp #VersionNb	; are swapped in lda	beq goodPtypeWrongType	lda UserhPrint+2,s	pha	lda UserhPrint+2,s	pha	_PrDefaultGoodPtype* if Print.PrJob.pIdleProc==NIL* Then Print.PrJob.pIdleProc:=@PrAbortCheck	lda hPrint+PrJob+pIdleProc+0	ora hPrint+PrJob+pIdleProc+2	bne useridle	lda #<PrAbortCheck	sta hPrint+PrJob+pIdleProc+0	lda #^PrAbortCheck	sta hPrint+PrJob+pIdleProc+2useridle* update the port	stz allowstatus	stz PortOpened	; Port not opened to start	stz NewInterval+0	; initialize timer used by	stz NewInterval+2	; status call	jsl myIdleProc	jsr OpenInfoPrinting	jsr OpenLaser	; try open PAP conn while show status and allowing user exit	bcc LaserOpened	; go on if successful	cmp #iPrAbort	; exit if user-cancel	beq @1	jsr OpenLaser	; try opening one additional time; some LW won't communicate	bcc LaserOpened	; if they are in the process of ejecting a page, etc	cmp #iPrAbort	beq @1	lda #PAPConnNotOpen	; if we couldn't establish communication then set error	sta iPrErr@1	brl ExitOpenDoc	; and exitLaserOpened;-----------------------------------------------------------;; Get the user name from the Print Manager and use it to set up the; jobname field in the LaserWriter's status dictionary.  AppleTalk; uses this information in its status message.; This is done even before the prep file is downloaded is so that the; status during the sending of the prep file shows the user name.;	pushlong #JobName1	jsr AddStrToWBuff	PushLong #0	; NIL may be important (18-Feb-93 DAL)	_PMGetUserName	; get pointer and leave it on	jsr AddStrToWBuff	; stack for this call	pushlong #JobName2	jsr AddStrToWBuff	PushLong #0	_PMGetDocName	; result is left on stack for	jsr AddStrToWBuff	; this call	pushlong #JobName3	jsr AddStrToWBuff	jsr WriteLaser	; Send this now because SendThePrep will		; start filling the buffer from the		; beginning, wiping out everything else	lda fPSFile	; non zero means writing to a file	beq @NoFile	lda #1	sta LWType	; when writing to file, assume LW Plus or II	bra GotNames	; no need to set up tables@NoFile	jsr SetUpNameTables	bcc GotNames	brl ExitOpenDoc	; error, most likely memory problemsGotNames;-----------------------------------------------------------;; Send PostScript header comments;	pushlong #JobTitleComment	jsr AddstrToWBuff	PushLong #0	_PMGetDocName	; result is left on stack for	jsr AddStrToWBuff	; this call	pushlong #ForUserComment	jsr AddstrToWBuff	PushLong #0	; NIL may be important (18-Feb-93 DAL)	_PMGetUserName	; get pointer and leave it on	jsr AddStrToWBuff	; stack for this call	pushlong #HeaderComment ; the rest of the stuff we don't deal with now	jsr AddstrToWBuff	jsr WriteLaser	; send everything in buffer now	jsl SendThePrep	; call to the dynamic segment to send	bcc GoUnload	; the prep stuff	lda iPrErr	; check if error is	a user cancel	cmp #iPrAbort	beq GoUnload	; yep	lda #PAPReadWriteErr ; otherwise it's a PAP error	sta iPrErrGoUnload	pha	pha	pha	; space for results	phx	phy	_UnloadSeg	; unload the dynamic segment	plx	plx	plx	; ignore results	lda iPrErr	beq ErrorFree	brl ExitOpenDocErrorFree	pushlong #EndPrologComment	jsr AddStrToWBuff	lda #false	sta ourport	lda SpPrPort,s	ora SpPrPort+2,s	bne Portexist* get a new Handle	lda #portsize		;size required	ldx #%1000000000011000 	;locked and dont cross bank	jsr OurGetHandle		;result on the stack	bcc @1	sta iPrErr	brl exitOpenDoc@1	sta QD_Temp1	stx QD_Temp1+2	lda [QD_Temp1]	sta SpPrPort,s	ldy #2	lda [QD_Temp1],y	sta SpPrPort+2,s	lda #true	sta ourportPortExist	lda SpPrPort,s		;update result	sta SResult,s	sta PZ_pPrPort	tax	lda SpPrPort+2,s	sta SResult+2,s	sta PZ_pPrPort+2* we open the port	pushlong PZ_pPrport	_OpenPort	bcc OK2	sta iPrErr	brl exitOpenDocOK2	dec PortOpened	; port has been opened	jsr installProcs* set portbits.boundsrect to 0,0,0,0	lda PZ_pPrPort	clc	adc #16	tax	lda PZ_pPrPort+2	adc #0	pha	phx	lda #0	pha	pha	pha	pha	_SetRect	stz iPageNum	;init page num* and open the file** reset the fonts	lda #0	sta FontList	sta PatternInstalled	dec a	sta curFontFamNum	sta curTxSize	sta curTxStyle* send the Header	jsr OpenDocHeader* set the pattern to black as default* it is possible that this small initialization will move* in openpage later, I don't know if "op" reset the grey level* in the laserprep.	lda #0	ldy #30blkloop	sta ourPat,y	dey	dey	bpl blkloop	stz PatternType	lda iPrErr	; should be 0 if alls wellexitOpenDoc	plb	pld	brl Exit8	ENDP**************************************************************** SpecialWrite  (SrcLoc : Long , Size :	word)** Routine called back from LoadThePrep to call the local* routine WriteLaser** This routine is called with 6 bytes of input on stack* which are stripped off on exit.***************************************************************	EXPORT SpecialWriteSpecialWrite	PROC	phb	; save dbr and set to this bank	phk	plb	lda Ptr+2,s	; copy the source to write buff	pha	lda Ptr+2,s	pha	PushLong #WriteBuffer	lda Count+8,s	PushWord #0	pha	_BlockMove	lda Count,s	; put count into write length	sta WriteLength	jsr WriteLaser	; writelaser and save status in y	php	php	ply	lda RTL,s	; clean the stack	sta RTL+6,s	lda RTL+1,s	sta RTL+6+1,s	plb	; restore dbr	pla	; more stack cleaning	pla	pla	phy	; restore status	plp	plp	rtl	; done	ENDP******************************************************************* SetUpNameTables - reads in list of available font names** inputs: none* outputs: none; returns with carry set if error (or user abort status)******************************************************************	EXPORT SetUpNameTablesSetUpNameTables	PROC	phd	; save QuickDraw's direct page	lda ZeroPage	tcd	; use our own;-----------------------------------------------------------;; Allocate a buffer of 512 bytes (flow quantum of AppleTalk) to begin with,; grow by 512 bytes as needed.;	lda #ATFlowQuantum+1 ; size of handle+1	sta rawBuffSize	; current size of the buffer+1 for easier compare	dec a	; back to actual size of ATFlowQuantum	ldx #%1000000000011000 ; locked, nonpurgeable, don't cross	jsr OurGetHandle	; bank boundaries, don't use special mem	bcc @1	sta iPrErr	brl ErrorExit@1	sta RawBuffHdl	; put the handle on zero page	stx RawBuffHdl+2	lda [RawBuffHdl]	; dereference the handle	sta RawBuffPtr	ldy #2	lda [RawBuffHdl],y	sta RawBuffPtr+2	stz BufferIndex	; start at beginning of buffer	dec allowstatus	; disable status gathering so no read is done		; background note: WriteLaser makes status calls		; which makes read calls	pushlong #Queries	; ask questions	jsr AddStrToWBuff	jsr WriteLaser	stz NumEntriesX2	; intialize the count;-----------------------------------------------------------;; First we deal with the response to the printer query;	lda iPrErr	; make sure no error pending => safe to do ReadLaser	beq OkToRead1	; this is because if err there might never be a response	brl ErrorExit	; BAK 9/16/91OkToRead1  	jsr ReadLaser;-----------------------------------------------------------;; Response format:;    1 LF(47.0)LF(product name)LF;; The product name string can be any of the following:;     (LaserWriter)		; length = 14;     (LaserWriter Plus)	; length = 19;     (LaserWriter II NT)	; length = 20;     (LaserWriter II NTX)	; length = 21;; We are interested in separating the product names into 3 catagories: non-LaserWriter,; LaserWriter, or LaserWriter Plus or LaserWriter II's.;	lda #LocalBuffer	; place where we have the printer type	clc	adc #11	; move pointer to start of product name string, not	sta destPtr	; including "("	lda #^LocalBuffer	sta destPtr+2	lda localBufSize	; the length of it	sec	sbc #11	; set to actual length of product name	sta destLen	pha	pushlong #destPtr	pushlong #destLen	pushlong #ProductName	; our search pattern	pushWord #11		; the length of target	PushLong #0		; no replacement string	PushWord #0	pushlong #Padding		; bogus pad char	_Munger	pla	; find the word LaserWriter?	bne NotLWFamily	; nope, not one of ours	ldx #1	; assume LW Plus or LW IIs	lda destLen	cmp #2	; if more than 2 chars ")LF" left, then	bne WeBeDone	; must be Plus or II	dex	; 0 = classic LW	bra WeBeDoneNotLWFamily	ldx #2	; 2 = non LW familyWeBeDone	stx LWType;-----------------------------------------------------------;; Now we get to the font list response;ReadLoop	lda iPrErr	; make sure no error pending => safe to do ReadLaser	beq OkToRead2	; this is because if err there might never be a response	brl ErrorExit	; BAK 9/16/91OkToRead2	jsr ReadLaser	; read the data via AppleTalk	lda LocalBufSize	cmp #2	; did we only read 2 chars -- "* LF"?	bne Continue	; no, keep going	lda LocalBuffer	; if we got 2 chars, then it may be the terminating	and #$00FF	; char "*" and its accompanied LF	cmp #'*'	bne Continue	brl BufferDoneContinue	inc NumEntriesX2	lda LocalBufSize	dec a	; we don't need the LF after the name	sta LocalBufSize	; this is now the actual length of the string	clc	adc BufferIndex	cmp rawBuffSize	blt BigEnough;-----------------------------------------------------------;; We'll need to grow the buffer to handle more data;	PushLong RawBuffHdl	; that's where our handle still is	_HUnLock	; first we unlock it	pha	; space for size	pha	PushLong RawBuffHdl	_GetHandleSize	; get current block size	pla	clc	adc #ATFlowQuantum+1 ; increase it by another bufferful	sta RawBuffSize	dec a	; real size of ATFlowQuantum	pha	; new size	PushLong RawBuffHdl	_SetHandleSize	; set new block size	bcc @1	sta iPrErr	brl ErrorExit@1	PushLong RawBuffHdl	; then we lock it back	_HLock	lda [RawBuffHdl]	; derefernce the handle	sta RawBuffPtr	ldy #2	lda [RawBuffHdl],y	sta RawBuffPtr+2BigEnough	ldy BufferIndex	; store the length byte	lda LocalBufSize	; note: high byte will be taken care of when we store	sta [RawBuffPtr],y	; the name	iny	; bump index by 1	pushlong #LocalBuffer	; move the data to our own buffer	lda RawBuffPtr+2	pha	tya	; Y has BufferIndex	clc	adc RawBuffPtr	pha	PushWord #0	; high byte of long	word is always 0	lda LocalBufSize 	; since buffer size is 512 max	pha	_BlockMove	lda LocalBufSize	clc	adc BufferIndex	inc a	sta BufferIndex	; advance the index	brl ReadLoopBufferDone	stz allowStatus	; enable status again	lda NumEntriesX2	; multiply by two for easier indexing	asl a	sta NumEntriesX2;-----------------------------------------------------------;; Parse the raw data buffer and set up length and offset tables accordingly;; The remainder of the table is length followed by name string.; Get memory for two tables, each with NumEntriesX2 bytes.;		; size is already in A	ldx #%1000000000011000 ; locked, nonpurgeable, don't cross	jsr OurGetHandle	; bank boundaries, don't use special mem	bcc @1	sta iPrErr	brl ErrorExit@1	sta LengTabPtr	; put the handle on zero page	stx LengTabPtr+2	lda [LengTabPtr]	; dereference	tax	; store in x temporarily till high	ldy #2	; word is done	lda [LengTabPtr],y	sta LengTabPtr+2	stx LengTabPtr	lda NumEntriesX2	; size of handle	ldx #%1000000000011000 ; locked, nonpurgeable, don't cross	jsr OurGetHandle	; bank boundaries, don't use special mem	bcc @2	sta iPrErr	brl ErrorExit@2	sta OffTabPtr	; put the handle on zero page	stx OffTabPtr+2	lda [OffTabPtr]	tax	; store in x temporarily till high	ldy #2	; word is done	lda [OffTabPtr],y	sta OffTabPtr+2	stx OffTabPtr;-----------------------------------------------------------;; Loop to disect the buffer to sort out the length and calculate an; offset to each name. Stuffs the tables accordingly.;	ldy #0	; initialize the indexes	sty EntryIndex	; the table index	sty buffIndex	; index currently is pointing at the length char		; of the first name entryloopGet	lda [RawBuffPtr],y	and #$00FF	; get length byte	ldy EntryIndex	; get the table index	sta [LengTabPtr],y	; put the length in its table	tax	; temporary holding tank	lda buffIndex	inc a	; move pass length byte	sta [OffTabPtr],y	; buffIndex now points at the beginning of the name		; store this in the offset table	iny	; bump the table index	iny	cpy NumEntriesX2	; check if we're done	beq AllDone	; yep	sty EntryIndex	; update index	txa	; put length back in A	clc	; advance the buffer index to the end of	adc buffIndex	; the name	inc a	sta buffIndex	tay	; put it in y for use	bra loopGetAllDone	lda #0ErrorExit	pld	; put QuickDraw's direct page back	cmp #1	rts	EXPORT NumEntriesX2NumEntriesX2	DS.B 2	; 2X total number of entries in the Font Directory		; size of the length and offset tablesEntryIndex	DS.B 2	; index to the name length and offset tablesBuffIndex	DS.B 2	; index to the name bufferrawBuffSize	DS.B 2	; current size of raw buffer+1	EXPORT LWTypeLWType	DS.B 2	; LaserWriter type: 0 = LW, 1 = LW+ or II,		;             	2 = not LW familydestPtr	DS.B 4destLen	DS.B 2Padding	DS.B 2	ENDP***************************************************************** PrCloseDoc** parameters:     pPrPort        ptr to	printing grafport*****************************************************************	EXPORT PrCloseDocPrCloseDoc	PROC	DefineStackDPage	word 0BReg	byte 0rtl1	block 3rtl2	block 3SpPrPort	long 0	pha	; save value of d	lda >iPrErr	cmp #PortNotOn	bne OKToContinue	plx	brl Exit4OKToContinue	pla	phd	tcd	phb	phk	plb;-----------------------------------------------------------;; Put us back into QuickDraw mode in case the application forgets; or errors out before it gets a chance to send the PostScriptEnd; PicComment.;	stz comments;------------------------------------------------------------------;; Check the flag to	see if we got as far as OpenPort in PrOpenDoc; without an error.	If not opened, no need to close it;	lda PortOpened	bne @1	brl UserPort* close the file here@1	pushlong #TrailerComment	jsr AddStrToWBuff	pushlong #CloseDoc	jsr AddStrToWBuff	pushlong #PagesComment	jsr AddStrToWBuff	lda iPageNum	jsr addacc	pushlong #EOFComment	jsr AddStrToWBuff	jsr WriteLaser	; send all the information in		; the write buffer now	bcc WriteOK	lda iPrErr	cmp #iPrAbort	beq WriteOK	lda #PAPReadWriteErr	sta iPrErr* close the port firstWriteOK	lda SpPrPort+2,s	pha	lda SpPrPort+2,s	pha	_ClosePort	bcc @1	sta iPrErr	brl exitCloseDoc@1	lda fPSFile	; are we writing to file?	bne DispNotNeeded	; yep, skip the disposal since the following		; buffers were never allocated	lda RawBuffHdl+2	pha	lda RawBuffHdl	pha	_DisposeHandle	pha	pha	lda LengTabPtr+2	pha	lda LengTabPtr	pha	_FindHandle	_DisposeHandle	pha	pha	lda OffTabPtr+2	pha	lda OffTabPtr	pha	_FindHandle	_DisposeHandleDispNotNeeded	lda ourPort	cmp #true	bne userport	pha	pha	; FindHandle result	lda SpPrPort+4+2,s	pha	lda SpPrPort+4+2,s	pha	_FindHandle	_DisposeHandle	sta iPrErruserport	jsr CloseLaser	; close the PAP connection	pushlong #DefaultDocName	_PMSetDocName	; reset the document name to default	jsr CloseInfo	; close status message box	jsr RestoreCursor	lda iPrErrExitCloseDoc	plb	pld	brl Exit4DefaultDocName	str 'Unknown'	; defaults the name to "Unknown"	ENDP***************************************************************** PrOpenPage** parameter:   pPrPort         ptr to printing grafport*              pPageFrame      ptr to rectangle for scaling****************************************************************	EXPORT PrOpenPagePrOpenPage	PROC	DefineStackDPage	word 0BReg	byte 0rtl1	block 3rtl2	block 3pPageFrame	long 0SpPrPort	long 0	pha	; save value of d	lda >iPrErr	beq SallRight	plx	brl Exit8SallRight	pla	phd	tcd	phb	phk	plb;--------------------------------------------------------------------;; Reinitialize the grafport for each new page;	lda SpPrPort+2,s	pha	lda SpPrPort+2,s	pha	_Setport	; this doen't need to be an InitPort	bcc @1	; as in ImageWriter	driver	sta iPrErr	brl exitOpenPage@1	inc iPageNum	lda iPrErr	beq ContinuepseudoExit	brl ExitNowContinue	lda ipagenum	cmp hprint+prjob+ifstpage	blt pseudoExit	dec a	cmp hprint+prjob+ilstpage	bge pseudoExit	pushlong #PageComment	jsr AddStrToWBuff	lda iPageNum	jsr addacc	pushlong #Return	jsr AddStrToWBuff	lda #1	sta OurPnSize	sta OurPnSize+2	stz Ourorigin	stz Ourorigin+2	stz OurPnPos	stz OurPnPos+2	stz PixelInstalled	; initialize each page for pixel maps;; initialize these variables so that font information is sent for each; new page;	lda #$FFFF	sta curFontFamNum	sta CurTxSize	sta CurTxStyle	pushlong #OpenPage	jsr AddStrToWBuff;---------------------------------------------------------------------;; Send the rPage rectangle to be used as the clip region at	start of; a page.;	pushlong #ClipStrStart	jsr AddStrToWBuff	lda hprint+prInfo+rPage+Top	sta CurClipRect+Top	jsr addacc	lda hprint+prInfo+rPage+Left	sta CurClipRect+Left	jsr addacc	lda hprint+prInfo+rPage+Bottom	sta CurClipRect+Bottom	jsr addacc	lda hprint+prInfo+rPage+Right	sta CurClipRect+Right	jsr addacc	pushlong #ClipStrEnd	jsr AddStrToWBuff	lda pPageFrame,s	sta QD_Temp2	ora pPageFrame+2,s	beq NoScale	lda pPageFrame+2,s	sta QD_Temp2+2	ldy #0loop	lda [QD_Temp2],y	phy	jsr addacc	ply	iny	iny	cpy #8	blt loop	pushlong #ScaleFr	jsr AddStrToWBuffNoScale;               pushlong #OpenPage1;               jsr	AddStrToWBuff;               pushlong #BuStr;               jsr	AddStrToWBuff;               pushlong #BnStr;               jsr	AddStrToWBuff	jsr color	; send the palette for the page	jsr ShowStatusExitNow	lda #0exitOpenPage	plb	pld	brl Exit8	ENDP****************************************************************** PrClosePage** parameter:   pPrPort         ptr to printing grafport*****************************************************************	EXPORT PrClosePagePrClosePage	PROC	pha	; save value of d	lda >iPrErr	beq GoOn	plx	brl Exit4GoOn	pla	phd	tcd	phb	phk	plb	lda ipagenum	cmp hprint+prjob+ifstpage	blt exitnow2	dec a	cmp hprint+prjob+ilstpage	bge exitnow2* ok call showpage now	pushlong #ClosePage	jsr AddStrToWBuff	jsr WriteLaser	bcc ExitNow2	lda iPrErr	cmp #iPrAbort	beq ExitClosePage	lda #PAPReadWriteErr	sta iPrErr	bra ExitClosePageExitnow2	lda #0ExitClosePage	plb	pld	brl Exit4	ENDP******************************************************************* Default abort procedure: polls keyboard for Command-period.** Also checks for Command-F which redirects the PostScript to a* file.******************************************************************	EXPORT PrAbortCheckPrAbortCheck	PROC	; should be in scc68kmore	pushword #0	pea %0000010000101000	pushlong #EventRecord	_GetNextEvent	pla	beq bye	lda evtmsg	cmp #'.'	; Check for Period	beq Abort	cmp #'F'	; Command-F ?	beq PSFile	cmp #'f'	bne morePSFile	lda evtmods	; command	and #$0100	beq more	inc fPSFile	bra byeAbort	lda evtmods	; command	and #$0100	beq more	lda #iPrAbort	sta iPrErrbye	rtl	ENDP******************************************************************* Calls the idle procedure******************************************************************	EXPORT MyIdleProcMyIdleProc	PROC	; should be in scc68k	lda hPrint+PrJob+pIdleProc+1	pha	phb	pla	lda hPrint+PrJob+pIdleProc	sec	sbc #1	pha	rtl	ENDP******************************************************************* OpenDocHeader*              no parameters on stack** Sends PostScript's conforming header information and infomation* needed to set up a document for printing on the LaserWriter.******************************************************************	EXPORT OpenDocHeaderOpenDocHeader	PROC;; Put our PostScript dictionary on the stack for use with this document;	pushlong #BeginDict	jsr AddStrToWBuff;; The following code sends the parameters necessary for the	page setup; procedure;; number of copies; allowing 999 copies as max, anything greater is set to 1 copy;	lda hprint+prjob+iCopies	cmp #1000	; the user doesn't really want	blt GoOn	; that many copies,	does he?	lda #1	; set copies to 1GoOn	jsr AddAcc;; test if manual feed is requested;	lda hprint+prStl+feed	beq ManualFeed	pushlong #FalseStr	bra ContinueManualFeed	pushlong #TrueStrContinue	jsr AddStrToWBuff;; test if Smoothing	is requested;	lda #f2	Smoothing	and hprint+prstl+wdev	beq trueSmooth	pushlong #FalseStr	bra FalseSmoothtrueSmooth	pushlong #TrueStrFalseSmooth	jsr AddStrToWBuff;; test if Portrait;	lda #f1	Portrait	and hprint+prstl+wdev	beq truePortrait	bra LandscapetruePortrait	pushlong #TrueStr	jsr AddStrToWBuff;; rPaper, the paper	rectangle;	lda hprint+rPaper+Top	jsr addacc	lda hprint+rPaper+Left	jsr addacc	lda hprint+rPaper+Bottom	jsr addacc	lda hprint+rPaper+Right	jsr addacc;; reduction;	lda hprint+prstl+reduced	jsr addacc;; iHres;	lda hprint+prInfo+iHRes	jsr addacc;; iVres;	lda hprint+prInfo+iVRes	jsr addacc	bra giveSelectLandscape	pushlong #FalseStr	jsr AddStrToWBuff;; rpaper, the paper	rectangle;	lda hprint+rPaper+Top	jsr addacc	lda hprint+rPaper+Left	jsr addacc	lda hprint+rPaper+Bottom	jsr addacc	lda hprint+rPaper+Right	jsr addacc;; reduction;	lda hprint+prstl+reduced	jsr addacc;; iVres	lda hprint+prInfo+iVRes	jsr addacc;; iHres;	lda hprint+prInfo+iHRes	jsr addaccgiveSelect;-----------------------------------------------------------------;; send the page size selection which is	given in 120th of an inch,; borrowed from the	Mac;	pushlong #SpaceChar	jsr AddStrToWBuff	lda hprint+prStl+PaperType	asl a	tax	lda pagesizeselection,x	jsr addacc	pushlong #OpenDoc	jsr AddStrToWBuff	rts	ENDP**********************************************************************	EXPORT DownLoadFileDownLoadFile	PROC	dec allowstatus	; don't allow status gathering	stz GSOSError	; reinitialize temp	variable	_OpenGS ParamOpen	bcs Exit	lda OpenRef	sta ReadRef	; put file refNum into parameter	sta CloseRef	; blocks for read and closeagain	_ReadGS ParamRead	; read file	bcs storeTemp	lda CarReaded	; if no char read, then done	beq finish	sta WriteLength	; else set length of buffer content	jsr WriteLaser	; and sent to LaserWriter	bcs DoPAPErrors	bra again	; go read some moreStoreTemp	cmp #EOFError	beq finish	; EOF is not a real	error	sta GSOSError	; put Read error in temp variable for laterfinish	_CloseGS ParamClose	; close up the file	lda GSOSError	; put error back in A-regExit	stz allowstatus	cmp #1	rtsDoPAPErrors	lda iPrErr	sta GSOSError	; preserve the error for later	cmp #iPrAbort	; user cancel?	beq Finish	; go close file and leave	lda #PAPReadWriteErr; some other PAP error	sta iPrErr	bra Finish	; go close file and leave;------------------------------------------------------------------;; Parameter blocks for open, read and close;ParamOpen	DC.W 2OpenRef	DC.W 0	; ref num	DC.L OpenFileName	; path nameParamRead	DC.W 4ReadRef	DC.W 0	; ref num	DC.L WriteBuffer	; data buffer pointer	DC.L 512	; bytes to be readCarReaded	DC.L 0	; actual bytes readParamClose	DC.W 1CloseRef	DC.W 0	; ref numGSOSError	DS.B 2	ENDP;                Copy    Color	EXPORT colorcolor	PROC	pushlong #arraystr1	jsr AddStrToWBuff	stz cptloop	lda #$9E00	sta QD_Temp2	lda #$00E1	sta QD_Temp2+2	lda cpt	asl a	tay	lda [QD_Temp2],y	and #$0FFF	pha	and #$000F	sta val	pla	lsr a	lsr a	lsr a	lsr a	pha	and #$000F	clc	adc val	sta val	pla	lsr a	lsr a	lsr a	lsr a	and #$000F	clc	adc val	jsr addacc	inc cpt	lda cpt	cmp #16	bne loop	pushlong #Arraystr2	jsr AddStrToWBuff	rtscpt	DS.B 2Val	DS.B 2	ENDP;                copy    LaserProcs	EXPORT LaserProcsLaserProcs	PROC	EXPORT installProcsinstallProcs* the user better hooks after the openpage** we put them in the current port	pushlong #DefaultProcs	_SetStdProcs	pushlong #ProcsTable	_SetStdProcs	lda #<text-1	sta ProcsTable	lda #^text-1	sta ProcsTable+2	lda #<Line-1	sta ProcsTable+4	lda #^Line-1	sta ProcsTable+6	lda #<Rect-1	sta ProcsTable+8	lda #^Rect-1	sta ProcsTable+10	lda #<Rrect-1	sta ProcsTable+12	lda #^Rrect-1	sta ProcsTable+14	lda #<Oval-1	sta ProcsTable+16	lda #^Oval-1	sta ProcsTable+18	lda #<Arc-1	sta ProcsTable+20	lda #^Arc-1	sta ProcsTable+22	lda #<Poly-1	sta ProcsTable+24	lda #^Poly-1	sta ProcsTable+26	lda #<Pixel-1	sta ProcsTable+32	lda #^Pixel-1	sta ProcsTable+34	lda #<Comment-1	sta ProcsTable+36	lda #^Comment-1	sta ProcsTable+38	pushlong #ProcsTable	_SetGrafProcs	rts	EXPORT ProcsTableProcsTable	DS.B 16*4	EXPORT DefaultProcsDefaultProcs	DS.B 16*4	ENDP;                Copy    PortOffset	EXPORT PortOffsetPortOffset	PROC	EXPORT StandardPortStandardPort	EXPORT xLocStartxLocStart	DC.W 0	; PortSCB	DC.L $E12000	; ImageRef	DC.W 160	; Width	DC.W 0,0,200,320	; BoundsRect	EXPORT xLocEndxLocEnd	DC.W 0,0,200,320	; PortRect	DC.L 0	; ClipRef	DC.L 0	; VisRef	DC.B $FF	; BkPat	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	EXPORT StdPnStateStdPnState	DC.W 0,0	; PnLoc	DC.W 1,1	; PnSize	DC.W 0	; PnMode	DC.B 0	; PnPat	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B $FF	; PnMask	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	EXPORT xEndPnStatexEndPnState	DC.W 0	; PnVis	DC.L 0	; FontHandle	DC.L 0	; FontID	DC.W 0	; FontFlags	DC.W 0	; TxSize	DC.W 0	; TxFace	DC.W 0	; TxMode	DC.L 0	; SpaceExtra is a fixed pt value	DC.L 0	; CharExtra is a fixed pt value	DC.W 0	; FGColor	DC.W $FFFF	; BGColor	DC.L 0	; PicSave	DC.L 0	; RgnSave	DC.L 0	; PolySave	DC.L 0	; GrafProcs	DC.W 0	; ArcRot	DC.L 0	; UserField	DC.L 0	; SystemField	EXPORT EndStandardPortEndStandardPort	ENDP;                copy    checkport	EXPORT checkportcheckport	PROC;-----------------------------------------------------------------;; QDport should still be valid even after a status update, since; restoring the saved port will restore	that pointer. The fill; pattern should also be valid, since the drawstring call used in; status update will not trash the pattern. DrawVerb is the	only; value in danger and it has been saved	before entering this routine.;; First check if origin has changed	ldy #8	lda [Qdport],y	cmp ourOrigin	bne newOrigin	iny	iny	lda [Qdport],y	cmp ourOrigin+2	beq sameoriginNewOrigin	ldy #8	lda [Qdport],y	sec	sbc OurOrigin	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	ldy #8+2	lda [Qdport],y	sec	sbc OurOrigin+2	jsr addacc	pushlong #xlstr	jsr AddStrToWBuff	ldy #8	lda [Qdport],y	sta OurOrigin	iny	iny	lda [Qdport],y	sta OurOrigin+2;----------------------------------------------------------------------;; Then check if any	clipping is to occur. Only rectangular clipping; regions are supported at this time.;sameorigin	ldy #oClipRgn	lda [QDPort],y	; get the handle to	the clip rgn	sta ScratchPtr1	iny	iny	lda [QDPort],y	sta ScratchPtr1+2	lda ScratchPtr1	ora ScratchPtr1+2	beq NoClipping	lda [ScratchPtr1]	; dereference	sta ScratchPtr2	ldy #2	lda [ScratchPtr1],y	sta ScratchPtr2+2	lda [ScratchPtr2]	cmp #10	; size for a rectangular clip region	bne NoClipping	; is 10 (2 byte size, 8 byte rect);-----------------------------------------------------------------------;; Check the clip region for two things:	is it the humongous	rect set at; the time when port is created and has	it changed from the last time?; CurClipRect is initialized at OpenPage time to rPage.;	stz SameClip	; initialize the flag	ldy #02LoopCheck	lda [ScratchPtr2],y	cmp hPrint+prInfo+rPage-2,y	beq InsideRpage	; equal or less than rpage?	blt InsideRpage	lda hPrint+prInfo+rPage-2,y ; use rpage	if notInsideRpage	sta LocalRect-2,y	; keep a local copy	cmp CurClipRect-2,y	; same as current clip rect?	beq isSameClip	inc SameClip	; not the same, so set flagisSameClip	iny	iny	cpy #10	blt LoopCheck	lda SameClip	beq NoClippingNewClip	pushlong #ClipStrStart	jsr AddStrToWBuff	ldy #0	; send the rectangleloop	phy	; hide the count on	the stack	lda LocalRect,y	sta CurClipRect,y	; save a copy in current clip rect	jsr AddAcc	; this routine trashes both x and y	ply	; get the count back	iny	; bump it	iny	cpy #08	blt loop	pushlong #ClipStrEnd	jsr AddStrToWBuffNoClipping	rtsSameClip	DS.B 2LocalRect	DS.B 8	EXPORT CheckVerbCheckVerb	ldx #32	; assume 320 mode to start	lda [Qdport]	; check SCB	and #$0080	beq GoOn	; 320, all set	ldx #16	; it's 640 modeGoOn	stx limit	lda SaveDrawVerb	cmp #FillVerb	bne nofill;-----------------------------------------------------------;; For a Fill, we check if the fill pattern is the same as the one that is already; in use. If so, we do nothing, otherwise we send the new pattern.;	ldx #0	; loop to check the patternLoopFillPat	phd	tdc	clc	adc #$0100	; TheFillPat is on QuickDraw's 2nd D page	tcd	lda TheFillPat,x	cmp ourPat,x	bne SendFillPat	pld	inx	inx	cpx limit	; limit is set based on the SCB	bne LoopFillPat	rtsSendFillPat	pld	ldx #0	; loop to send the new patternLoopSendFill	phd	tdc	clc	adc #$0100	tcd	lda TheFillPat,x	sta ourPat,x	pld	inx	inx	cpx limit	bne LoopSendFill	jsr sendourpat	rtsNoFill	cmp #EraseVerb	bne noErase;-----------------------------------------------------------;; For an Erase, we check if the background pattern is the same as the one that is; already in use. If so, we do nothing, otherwise we send the new pattern.;	ldx #0	; loop to check the pattern	ldy #oBkPatLoopBkPat	lda [QDPort],y	cmp ourpat,x	bne SendBkPat	inx	inx	iny	iny	cpx limit	; limit is set based on the SCB	bne LoopBkPat	rtsSendBkPat	ldx #0	; loop to send the new pattern	ldy #oBkPatLoopSendBk	lda [QDPort],y	sta ourPat,x	inx	inx	iny	iny	cpx limit	bne LoopSendBk	jsr SendOurPat	rtsnoErase	cmp #InvertVerb	; do nothing for invert	beq leave	jsr wCheckPen	; do this for frame and paintleave	rtslimit	DS.B 2;-----------------------------------------------------------;;	EXPORT wCheckPenwCheckPen	ldy #oPnSize	lda [QDPort],y	cmp OurPnSize-oPnSize,y	bne NewSize	iny	iny	lda [QDPort],y	cmp OurPnSize-oPnSize,y	beq checkmodeNewSize	ldy #oPnSize	;height	lda [QDPort],y	sta OurPnSize-oPnSize,y update our port	jsr addacc	ldy #oPnSize+2	;width	lda [QDPort],y	sta OurPnSize-oPnSize,y update our port	jsr addacc	pushlong #PenStr	jsr AddStrToWBuffCheckMode	ldy #oPnmode	lda [QDPort],y	cmp OurPnMode-oPnmode,y	beq checkPat	ldy #oPnmode	lda [QDPort],y	sta OurPnMode-oPnmode,y update our portcheckPat	ldx #32	; assume 320 mode to start	lda [Qdport]	; check SCB	and #$0080	beq GoOn1	; 320, all set	ldx #16	; it's 640 modeGoOn1	stx limit	ldx #0	; loop to check the pattern	ldy #oPnPatLoopPnPat	lda [QDPort],y	cmp ourpat,x	bne SendPnPat	inx	inx	iny	iny	cpx limit	; limit is set based on the SCB	bne LoopPnPat	rtsSendPnPat	ldx #0	; loop to send the new pattern	ldy #oPnPatLoopSendPn	lda [QDPort],y	sta ourPat,x	inx	inx	iny	iny	cpx limit	bne LoopSendPn	jsr SendOurPat	rts;-----------------------------------------------------------;; CheckForeGroundColor: used by text routine only;	EXPORT CheckFgColorcheckFgColor	ldx #32	; assume 320 mode to start	lda [Qdport]	; check SCB	and #$0080	beq GoOn2	; 320, all set	ldx #16	; it's 640 modeGoOn2	stx limit	ldx #0	; loop to check foreground color	ldy #oFgColor	lda [QDPort],yLoopCkFgColor	cmp ourpat,x	bne SendFgColor	inx	inx	cpx limit	; limit is set based on the SCB	bne LoopCkFgColor	rtsSendFgColor	ldx #0	; loop to send the new foreground color	ldy #oFgColor	; as a solid pattern	lda [QDPort],yLoopSendFgColor	sta ourPat,x	inx	inx	cpx limit	bne LoopSendFgColor	jsr SendOurPat	rts;-----------------------------------------------------------;;	EXPORT setblacksetblackdoblack	lda #0	ldy #30blkloop	sta ourPat,y	dey	dey	bpl blkloop	lda PatternType	cmp #2	bne alreadyBlk	pushlong #OrigScreen	jsr AddStrToWBuffalreadyBlk	lda #0	jsr addacc	pushlong #SetGray	jsr AddStrToWBuff	stz PatternType	rts	EXPORT setWhitesetWhitedoWhitez	lda #$00FF	ldy #30whtloop	sta ourPat,y	dey	dey	bpl whtloop	lda PatternType	cmp #2	bne alreadyWht	pushlong #OrigScreen	jsr AddStrToWBuffalreadyWht	lda #1	jsr addacc	pushlong #SetGray	jsr AddStrToWBuff	lda #1	sta PatternType	rtssendourpat* test Black first	ldy #30	; 32 byte pattern for 320 mode	lda [QDPort]	and #$0080	beq SOP320	ldy #14	; only 16 bytes for	640 modeSOP320	phy	; tug away twice, once for later use	phy	lda #$0000SOPLoop1	ora OurPat,y	dey	dey	bpl SOPLoop1	and #$FFFF	beq itsAllBlack	ply	lda #$FFFFSOPLoop2	and OurPat,y	dey	dey	bpl SOPLoop2	cmp #$FFFF	beq itsAllWhite	lda #2	sta PatternType	stz solidPat	; assume solid till	proven otherwise	pushlong #OpenHex	jsr AddStrToWBuff	ply	; get the index we hid earlier on stack	ldx #0SOPLoop3	lda ourpat,x	cmp ourpat	; match this word to the first word of	beq same	; the pattern	inc solidPat	; if not same, pattern is not solidsame	phx	phy	jsr addHexWord	ply	plx	inx	inx	dey	dey	bpl SOPLoop3	pushlong #CloseHex	; mark the end of the hex string	jsr AddStrToWBuff;---------------------------------------------------------------------;; Check to see if the pattern is a solid color or a real honest to; goodness pattern;	lda solidPat	beq solid	pushlong #FalseStr	bra onwardsolid	pushlong #TrueStronward	jsr AddStrToWBuff	lda [QDPort]	and #$0080	; is it 320 mode	beq M320	pushlong #TrueStr	; nope, it's 640	bra DoItM320	pushlong #FalseStr	; yep, 320DoIt	jsr AddStrToWBuff	pushlong #PatStr	jsr AddStrToWBuff	rtsitsAllBlack	ply	ply	brl doBlackitsAllWhite	ply	brl doWhitezsolidPat	DS.B 2	ENDP****************************************************************** Rect (arc, oval, poly, etc.)** Current Rev: Dec 14, 1987** Revised to use new PostScript - GSPrep*****************************************************************	EXPORT RectRect	PROC	jsr testSave	beq doRect	lda >DefaultProcs+9	pha	phb	pla	lda >DefaultProcs+8	pha	rtlDorect	phb	phk	plb	lda iPrErr	beq Continueexitnow	brl ExitRectContinue;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code to; the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow	ldy #opnVis	lda [Qdport],y	bmi exitnow	jsr SaveStuff	; go save DrawVerb and Rect1	jsr checkport	jsr CheckVerb	pushlong #return	;start with a return	jsr AddStrToWBuff	lda SaveY1	;then top	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX1	;left	jsr AddAcc	pushlong #SpaceChar	;space	jsr AddStrToWBuff	lda SaveY2	;bottom	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX2	;right	jsr AddAcc	lda SaveDrawVerb	;Verb	jsr addacc	pushlong #drawrect	;rc	jsr AddStrToWBuffExitRect	lda #0	clc	plb	rtl	ENDP*****************************************************************	EXPORT LineLine	PROC	jsr testSave	beq DoLine	lda >DefaultProcs+5	pha	phb	pla	lda >DefaultProcs+4	pha	rtlDoLine	phb	phk	plb	lda iPrErr	beq Continue2exitnow2	brl ExitLineContinue2;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code to; the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow2	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow2	ldy #opnVis	lda [Qdport],y	bmi exitnow2	jsr SaveStuff	; go save DrawVerb and Rect1	jsr checkport	; check if origin has changed	jsr wcheckpen	; check if pen size	has changed	lda SaveX1	sta penpos+2	; borrowing penpos to use as a	lda SaveY1	; temp variable	sta penpos	pushlong penpos	jsr addCoordinate	pushlong #Moveto	jsr AddStrToWBuff	lda SaveX2	sta penpos+2	lda SaveY2	sta penpos	pushlong penpos	jsr addCoordinate	pushlong #Lineto	jsr AddStrToWBuffExitLine	lda #0	clc	plb	rtl	ENDP*****************************************************************	EXPORT ovaloval	PROC	jsr testSave	beq DoOval	lda >DefaultProcs+17	pha	phb	pla	lda >DefaultProcs+16	pha	rtlDoOval	phb	phk	plb	lda iPrErr	beq Continue3ExitNow3	brl ExitOvalContinue3;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code to; the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow3	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow3	ldy #opnVis	lda [Qdport],y	bmi exitnow3	jsr SaveStuff	; go save DrawVerb and Rect1	jsr checkport	jsr checkVerb	pushlong #return	;start with a return	jsr AddStrToWBuff	lda SaveY1	;then top	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX1	;left	jsr AddAcc	pushlong #SpaceChar	;space	jsr AddStrToWBuff	lda SaveY2	;bottom	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX2	;right	jsr AddAcc	lda SaveDrawVerb	;Verb	jsr addacc	pushlong #drawoval	;ov	jsr AddStrToWBuffExitOval	lda #0	clc	plb	rtl	ENDP*****************************************************************	EXPORT RrectRrect	PROC	jsr testSave	beq DoRrect	lda >DefaultProcs+13	pha	phb	pla	lda >DefaultProcs+12	pha	rtlDoRrect	phb	phk	plb	lda iPrErr	beq Continue4ExitNow4	brl ExitRrectContinue4;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code to; the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow4	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow4	ldy #opnVis	lda [Qdport],y	bmi exitnow4	jsr SaveStuff	; go save DrawVerb and Rect1	ldx #$0200	lda OvalWidth,x	; save these values	too	sta SaveOvlWidth	lda OvalHeight,x	sta SaveOvlHeight	jsr checkport	jsr CheckVerb	pushlong #return	;start with a return	jsr AddStrToWBuff	lda SaveY1	;then top	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX1	;left	jsr AddAcc	pushlong #SpaceChar	;space	jsr AddStrToWBuff	lda SaveY2	;bottom	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX2	;right	jsr AddAcc	lda SaveOvlHeight	jsr addacc	lda SaveOvlWidth	jsr addacc	lda SaveDrawVerb	;Verb	jsr addacc	pushlong #drawrrect	;rc	jsr AddStrToWBuffExitRrect	lda #0	clc	plb	rtlSaveOvlWidth	DS.B 2SaveOvlHeight	DS.B 2	ENDP*****************************************************************	EXPORT ArcArc	PROC	jsr testSave	beq DoArc	lda >DefaultProcs+21	pha	phb	pla	lda >DefaultProcs+20	pha	rtlDoArc	phb	phk	plb	lda iPrErr	beq Continue5Exitnow5	brl ExitArcContinue5;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code to; the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow5	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow5	ldy #opnVis	lda [Qdport],y	bmi exitnow5	jsr SaveStuff	; go save DrawVerb and Rect1	lda StartAngle	; save these values	too	sta SaveStartAngle	lda ArcAngle	sta SaveArcAngle	jsr checkport	jsr CheckVerb	pushlong #return	;start with a return	jsr AddStrToWBuff	lda SaveY1	;then top	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX1	;left	jsr AddAcc	pushlong #SpaceChar	;space	jsr AddStrToWBuff	lda SaveY2	;bottom	jsr AddAcc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveX2	;right	jsr AddAcc	lda SaveStartAngle	sec	sbc #90	jsr addacc	lda SaveStartAngle	sec	sbc #90	clc	adc SaveArcAngle	jsr addacc	lda SaveDrawVerb	;Verb	jsr addacc	pushlong #drawArc	;rc	jsr AddStrToWBuffExitArc	lda #0	clc	plb	rtlSaveStartAngle	DS.B 2SaveArcAngle	DS.B 2	ENDP*****************************************************************	EXPORT PolyPoly	PROC	phb	phk	plb	lda iPrErr	beq Continue6exitnow6	brl ExitPolyContinue6;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code to; the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow6	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow6	ldy #opnVis	lda [Qdport],y	bmi exitnow6	jsr SaveStuff	; go save DrawVerb and Rect1	lda RgnHandleA	; save the region handle	sta SaveRgnHandleA	lda RgnHandleA+2	sta SaveRgnHandleA+2	jsr checkport	jsr CheckVerb	lda SaveRgnHandleA	; restore handle	sta RgnHandleA	lda SaveRgnHandleA+2	sta RgnHandleA+2	lda [RgnHandleA]	sta RgnPtrA	sta SaveRgnPtrA	; save a copy locally	ldy #2	lda [RgnHandleA],y	sta RgnPtrA+2	sta SaveRgnPtrA+2	lda [RgnPtrA]	sta PolySize	cmp #$0012	bge bigenough	brl exitpolybigenough	ldy #$000C	;first point	sty CurPoint	lda [RgnPtrA],y	pha	dey	dey	lda [RgnPtrA],y	pha	jsr addCoordinate	pushlong #Moveto	jsr AddStrToWBuff* first move to completed	lda Curpoint	clc	adc #4	sta Curpoint	lda SaveDrawVerb	;just allow the framerect	beq Frame1	pushlong #StartPoly	jsr AddStrToWBuffFrame1onemore	lda SaveRgnPtrA	; restore pointer before using	sta RgnPtrA	lda SaveRgnPtrA+2	sta RgnPtrA+2	ldy CurPoint	lda [RgnPtrA],y	pha	dey	dey	lda [RgnPtrA],y	pha	jsr addCoordinate	lda SaveDrawVerb	beq Frame2	pushlong #PolyLine	jsr AddStrToWBuff	bra Frame25Frame2	pushlong #LineTo	jsr AddStrToWBuffFrame25	lda Curpoint	clc	adc #4	sta Curpoint	cmp PolySize	blt onemore	lda SaveRgnPtrA+0	; restore pointer before using	sta RgnPtrA+0	lda SaveRgnPtrA+2	sta RgnPtrA+2	ldy #$000C	;first point again	lda [RgnPtrA],y	pha	dey	dey	lda [RgnPtrA],y	pha	jsr addCoordinate	lda SaveDrawVerb	beq Frame4	pushlong #PolyLine	jsr AddStrToWBuff	bra Frame45Frame4	pushlong #LineTo	jsr AddStrToWBuffFrame45	lda SaveDrawVerb	beq Frame3	pushlong #EndPoly	jsr AddStrToWBuffFrame3ExitPoly	lda #0	clc	plb	rtlPolySize	DS.B 2CurPoint	DS.B 2SaveRgnHandleA	DS.B 4SaveRgnPtrA	DS.B 4	ENDP******************************************************************* SaveStuff** Saves DrawVerb and Rect1 (y1,x1,y2,x2) in local variables******************************************************************	EXPORT SaveStuffSaveStuff	PROC	lda DrawVerb	sta SaveDrawVerb	ldx #06	; moves 8 bytes of the rectangleLoopSave	lda y1,x	sta SaveY1,x	dex	dex	bpl LoopSave	rts	ENDP**************************************************************              			** Text             			**              			** Revised to use new PostScript - PrepFile     	** Also new format for downloading bitmap fonts     	**             	 		**************************************************************	EXPORT TextText	PROC	phb	phk	plb	lda iPrErr	beq ContinueExitNow	brl ExitTextContinue;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code; to the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow;-----------------------------------------------------------;; Set up quickdraw's direct page with the proper font info;	lda #0	; always use fontmgr info when zero	jsl SetUpFontInfo;----------------------------------------------------------------------;; Check if any PicComments are being used;	lda Comments	bmi exitNow	; -1 denotes some comment in use		; that text doesn't care about	cmp #1	; if it's 0, go on as usual	bne NoComments;----------------------------------------------------------------------;; 1 denotes that PSText is in effect, so we need to deal with it;	lda DrawVerb	bne NextCheck	jsr SendOneChar	; Draw verb = 0: DrawChar	bra SendNowNextCheck	cmp #DrawTextVerb	beq NormText	jsr SendCStr	; Draw verb = 2: DrawCString	bra SendNowNormText	jsr SendText	; Draw verb = 1: normal stringSendNow	jsr AddTextToWBuff	brl exitText;----------------------------------------------------------------------;; PicComments not used, business as usual;NoComments	ldy #opnVis	lda [Qdport],y	bmi ExitNow;----------------------------------------------------------------------;; If drawverb is either drawtext or drawCstring then check if the; string is empty, if so, skip this routine to save time and grief; We look at the QD's DrawVerb to see if normal string or CString.; If normal, we check if textlength is 0, if Cstring, we need to loop; till the end to find out if empty.;	lda DrawVerb	beq dotext	; if drawchar, then	go on	cmp #2	; normal strings are 1	blt checklength	sep #$20	longa off	ldy #0	; start the Cstring	loopOnceAgain	lda [textPtr],y	beq endCstr	; last char of Cstring is 0	iny	bra OnceAgainEndCstr	rep #$20	longa on	cpy #0	; Cstring length 0?	beq ExitNow	; yep, we quit	bne doText	; nope, we go do the textCheckLength	lda textLength	; check text length	in QD's data	beq ExitNowdotext;---------------------------------------------------------------;; Save all the necessary values from QD's zero page into local; variables. These local variables will	be used throughout the; code, with the exception of TextPtr. It needs to be restored; each time before use because it's used for indirect indexed; addressing off zero page.;	lda DrawVerb	sta SaveDrawVerb	; this var declared	in MainData	lda textLength	sta SaveTextLength	lda CharToDraw	sta SaveCharToDraw	lda textPtr+0	sta SaveTextPtr+0	lda textPtr+2	sta SaveTextPtr+2	jsr checkPort	jsr CheckFgColor	; text is effected by foreground color	pushlong #PenPos	; get current pen position	_GetPen               ;jsr	setblack     ; ????? Cause of StyleWare's complaint		; about text in all black ???	ldy #oFontID	lda [QdPort],y	; only checking the family number portion	cmp curFontFamNum	; of the font ID	bne NotSame	ldy #oTxSize	lda [QdPort],y	and #$00FF	cmp curTxSize	bne NotSame	ldy #oTxFace	lda [QdPort],y	and #$00FF	cmp curTxStyle	bne NotSame	brl SameFontNotSame	ldy #oTxFace	lda [QdPort],y	and #$00FF	sta curTxStyle	jsr addacc	ldy #oTxSize	lda [QdPort],y	and #$00FF	sta curTxSize	bne good	; force it to 8 if 0 font size	lda #8good	jsr addacc	pushlong #Textsfs	jsr AddStrToWBuff	ldy #oFontID	; get the family number portion of fontID	lda [QDPort],y	sta curFontFamNum	pha	; result	pha	; family number	pushlong #ModName	; put the name in this string temporarily	_GetFamInfo	pla	; ignore the famStatBits for now;-----------------------------------------------------------;; copy the name from the temp string to curFontName, stripping spaces along the way.;	ldx #1	; start with first char of string	ldy #1	sep #$0030	longa offloopStrip	lda modName,x	cmp #' '	; see if it is a space	beq SkipSpace	; if so, skip it	sta curFontName,y	; if not space, store it in curFontName string	iny	; bump destination indexSkipSpace	inx	; bump source index	cpx modName	; whole string done?	blt loopStrip	; not if less than length	beq loopStrip	; and not if equal to length	dey	; length is one less	sty curFontName	; update source's length	longa on	rep #$0030;-----------------------------------------------------------;; Check and handle font substitution: check curfontname for the three fonts that can; be substituted:;            New York -- Times;            Geneva -- Helvetica;            Monaco -- Courier;	lda #f3	; check if font substitution is requested	and hPrint+prStl+wDev	bne NoSubstitute	; none requested, go the normal route;-----------------------------------------------------------;	lda curFontName	and #$00FF	tax	; use length as index	cmp #8	bge NoSubstitute	; font name is too long	cmp #6	blt NoSubstitute	; too short	sep #$0020	longa off	beq loopCheckMonaco	; if font name is 6 chars long, go check for		; Geneva or Monaco, else check if New YorkloopCheckNY	lda curFontName,x	cmp NewYorkStr,x	bne NotSubFont	dex	bne loopCheckNY	lda TimesStr	; substitute Times for New York	and #$00FF	taxloopSubNY	lda TimesStr,x	sta curFontName,x	dex	bpl loopSubNY	lda #3	; Times' position in the Font Name table	sta FNTabIndex	bra MovingAlongloopCheckMonaco	lda curFontName,x	cmp MonacoStr,x	bne NotMonaco	dex	bne loopCheckMonaco	lda CourierStr	; substitute Courier for Monaco	and #$00FF	taxloopSubMonaco	lda CourierStr,x	sta curFontName,x	dex	bpl loopSubMonaco	lda #1	; Courier's position in the Font Name table	sta FNTabIndex	bra MovingAlongNotMonaco	ldx #6loopCheckGeneva	lda curFontName,x	cmp GenevaStr,x	bne NotSubFont	dex	bne loopCheckGeneva	lda HelveticaStr	; substitute Helvetica for Geneva	and #$00FF	taxloopSubGeneva	lda HelveticaStr,x	sta curFontName,x	dex	bpl loopSubGeneva	lda #2	; Helvetica's position in the Font Name table	sta FNTabIndexMovingAlong	longa on	rep #$0020	bra GotAMatch	; go do style modsNotSubFont	longa on	rep #$0020;-----------------------------------------------------------;; Check to see if this is a font we know about. We keep a table of LaserWriter+; fonts, Shaston (made with Helvetica), and Sonata & Carta, graphics fonts which; doesn't need reencoding.;NoSubstitute	lda #-1	sta FNTabIndex	; assume a font that we don't know about	ldx #8	; assume we are working with an old LW which only		; has 4 built-in fonts, plus Shaston, our ROM font,		; and the graphic fonts: Sonata, Carta, Zapf Dingbats	lda LWType	; what kind of LaserWriter are we dealing with	beq checkEm	ldx #14	; it's a LW+ or a LW II, with 11 built-in fonts,		; and Shaston, our ROM font, and Sonata & CartacheckEm	stx limit	; use to determine when to stop looking	ldx #0 	; start at beginning of table	sep #$0020	longa off	lda curFontName	; first check the lengthloopCheckLeng	cmp FNLengTable,x	bne KeepOnLooking	; not same length, not same string	longa on	rep #$0020		; same length, maybe a match	stx FNTabIndex	; this index will come in handy again later	tay	; put curFontName's length in Y for later use	txa	asl a	asl a	; 4 bytes for each address entry	tax	lda FNAddrTable,x	; put the pointer to the string on zero page	sta QD_Temp1	lda FNAddrTable+2,x	sta QD_Temp1+2	sep #$0020	longa offloopCheckStr	lda [QD_Temp1],y	; check string for a match	cmp curFontName,y	bne NotThisFont	; oops, false alarm	dey	bne loopCheckStr	; keep checking	bra GotAMatch	; till whole string is matchedNotThisFont	lda curFontName	; set up the conditions again for	ldx FNTabIndex	; another time through	ldy #-1	; reinitialize this value, since we	sty FNTabIndex	; have no matchKeepOnLooking	inx	cpx limit	; end of table yet?	blt loopCheckLengGotAMatch	longa on	rep #$0020	lda FNTabIndex	bmi NotKnownFonts	; it's not a font we special case on	asl a	asl a	asl a	asl a	; 4 styles at 4 bytes each	sta FontStlIndex	; index to the first style of this font;-----------------------------------------------------------;; Bits 0 and 1 of curTxStyle determines	one of 4 LaserWriter typefaces; of each font to use.; 00 -- plain; 01 -- bold; 10 -- italic; 11 -- bold italic;	lda curTxStyle	; use the bold and italics bits to	and #03	; calculate an index within the 4 styles	asl a	; 4 bytes per entry	asl a	clc	adc FontStlIndex	; add to first style to get the true index	tax	lda StyleTable,x	sta QD_Temp1	; put in zero page for indirect addr for leng	inc a	; bump it to point to the start of string	sta FullFNPtr	; and store it in pointer	lda StyleTable+2,x	sta FullFNPtr+2	sta QD_Temp1+2	lda [QD_Temp1]	; get the length of the string	and #$00FF	sta FullFNLeng	bra BufferSearch	; all set up, go search the buffer;-----------------------------------------------------------;; Got a font we're not familiar with, attempt to make it generic by attaching; a general style mod to the name;NotKnownFonts	lda curTxStyle	; check the bold and italics bits	and #03	asl a	; 4 bytes per entry	asl a	tax	; use as index to style mod table	lda StyleModTable,x	sta QD_Temp1	lda StyleModTable+2,x	sta QD_Temp1+2	lda [QD_Temp1]	and #$00FF	tay	; use leng as index to chars of style mod string	clc	adc curFontName	; update length of name string	and #$00FF	sta modName	sta FullFNLeng	; set up full name string length	tax	; new leng as index to name string	sep #$0020	longa off	cpy #0	; if style mod string is 0, no suffix is needed	beq LoopNameLoopMod	lda [QD_Temp1],y	; start from the end of the string and copy	sta modName,x	; the style mod first	dex	dey	bne LoopMod		; and then the name itselfLoopName	lda curFontName,x	; x should be the length of the name itself	sta modName,x	; at this point	dex	bne LoopName	longa on	rep #$0020	lda #modName+1	; set up pointer	sta FullFNPtr	lda #^modName	sta FullFNPtr+2;-----------------------------------------------------------;; Now, match the composed name to the names in the LaserWriter's font directory;BufferSearch	lda fPSFile	; non zero means writing to a file	beq @1	; no need to search tables	brl NoTabSearch@1	lda FNTabIndex	bmi DoSearch	; an unknown font, should always search buff	cmp #Sonata_Num	; Any font whose index is less than Sonata is a	bge @2	; built-in LaserWriter font, so no buffer search	brl NoTabSearch	; is needed@2	cmp #ZapfDingbats_Num ; everything else in the table are LaserWriter	blt DoSearch	; Plus built-in fonts	lda LWType	; if we are dealing with a LaserWriter+ or II, no	cmp #1	; search is needed	beq NoTabSearchDoSearch	phd	; save QD's zero page	lda ZeroPage	; use our own	tcd	jsr DoBuffSearch	bcc GotIt;-----------------------------------------------------------;; IF we get here, it means we found nothing in the buffer to match the style modified; name. Try again using the unmodified name to find the plain font. The output is; of better quality if we let PostScript make the style mod than if we use the bitmap.;	lda curTxStyle	; check if we need any style mods	and #03	beq MakeIt	; nope, and the plain font is not found,		; go use the bitmap	lda curFontName	; use the plain name	and #$00FF	sta FullFNLeng	; set up length	lda #curFontName+1	; set up pointer	sta FullFNPtr	lda #^curFontName	sta FullFNPtr+2	jsr DoBuffSearch	; search again	bcs MakeIt	; found nothing, use bitmap	pld	; get QD's zero page back	pushlong #UpVmStr	; we found the plain font so we use it	jsr AddStrToWBuff	pushlong #AppleFontPrefix	jsr AddStrToWBuff	pushlong #curFontName	jsr AddStrToWBuff	pushlong #Slash	jsr AddStrToWBuff	pushlong #curFontName	jsr AddStrToWBuff	pushlong #TrueStr	jsr AddStrToWBuff	pushlong #CoorFontStr	jsr AddStrToWBuff	brl SendFontName	; the rest is the same as if we made the		; font from a bitmapMakeIt	pld	; get QD's zero page back	brl doMakeFont;-----------------------------------------------------------;; IF we get here, it means we found the font in the buffer. Sort out a few special; cases and send the appropriate PostScript.;GotIt	pld	; get QD's zero page backNoTabSearch	pushlong #UpVmStr	jsr AddStrToWBuff	pushlong #AppleFontPrefix	jsr AddStrToWBuff	lda FNTabIndex	bne NotShaston1	; 0 = Shaston	lda curTxStyle	; check the bold and italics bits	and #03	asl a	; 4 bytes per entry	asl a	tax	; use as index to style mod table	lda ShastonTable+2,x ; get Shaston's name	pha	lda ShastonTable,x	pha	bra ToContinue1NotShaston1	lda FullFNPtr+2	; name of font	pha	lda FullFNPtr	dec a	; so it now points at length byte	phaToContinue1	jsr AddStrToWBuff	pushlong #Slash	jsr AddStrToWBuff	lda FullFNPtr+2	pha	lda FullFNPtr	dec a	; so it now points at length byte	pha	jsr AddStrToWBuff	lda FNTabIndex	; Symbol, ZapfDingbats, Sonata and Carta are	cmp #Symbol_Num	; graphics fonts which do not need to be	blt Reencode	; reencoded with the Apple's own encoding	cmp #ZapfDingbats_Num+1	; vector	bge Reencode	pushlong #FalseStr	bra SendBoolReencode	pushlong #TrueStrSendBool	jsr AddStrToWBuff	pushlong #CoorFontStr	jsr AddStrToWBuff	pushlong #AppleFontPrefix	jsr AddStrToWBuff	lda FNTabIndex	bne NotShaston2	; 0 = Shaston	lda curTxStyle	; check the bold and italics bits	and #03	asl a	; 4 bytes per entry	asl a	tax	; use as index to style mod table	lda ShastonTable+2,x ; send Shaston's name	pha	lda ShastonTable,x	pha	bra ToContinue2NotShaston2	lda FullFNPtr+2	; font name	pha	lda FullFNPtr	dec a	; so it now points at length byte	phaToContinue2	jsr AddStrToWBuff;-----------------------------------------------------------;; Some more special casing for style modifications for Courier; it needs only; outline and shadow, bold and italics is already built in.;	lda FNTabIndex	cmp #Courier_Num	; is this Courier?	bne OutlineFont	; nope, treat as normal Adobe		; outline font	pushlong #ClrItalics	; no italics	jsr AddStrToWBuff	brl MakeOutlinesOutlineFont;-------------------------------------------------------------------;; CurTxStyle's value determines what font definition procedure in the prep file; to call:;      0 - 7  -- gf, defines a filled font (bit 3 not set, so call "gf" (get font and make current));      8 - 15 -- F aos, defines a outline font (bit 3 set, so call "aos" with arg=false);     16 - 31 -- T aos, defines a shadow font (bit 4 set, so call "aos" with arg=true);	pushlong #ClrItalics	; clear the italics flag, not	jsr AddStrToWBuff		; needed for LW fonts	lda curTxStyle	cmp #16		; shadow fonts are from 16 - 31	blt NotShadow	pushlong #DoShadowStr	bra SendItNotShadow	cmp #8		; outline fonts are	from 8 - 15	blt NotOutline	pushlong #DoOutlineStr	bra SendItNotOutline	pushlong #TextgfSendIt	jsr AddStrToWBuffAllSame	pushlong #DnStr	jsr AddStrToWBuffSameFont	lda penpos+2	pha	lda penpos+0	pha	jsr addCoordinate		; ps cmd to move currentpoint there	pushlong #Moveto	jsr AddStrToWBuff;               pushlong #TextBNPW;               jsr	AddStrToWBuff	pushlong #Textbt		; call "begin text" ps routine from prep	jsr AddStrToWBuff	pushlong #StartString	; ps openparen -- starts string	jsr AddStrToWBuff;-------------------------------------------------------------------;; Restore CharToDraw, TextPtr and TextLength at this time;	lda SaveCharToDraw	sta CharToDraw	lda SaveTextPtr+0	sta textPtr+0	lda SaveTextPtr+2	sta textPtr+2	lda SaveTextLength	sta textLength;--------------------------------------------------------------------;; We treat the text	being sent differently depending on its	type:; Char, C String or	Text;	pushword #0	lda SaveDrawVerb	bne CheckDrawVerb	jsr SendOneChar		; Draw verb = 0: DrawChar	bra Common		; routine puts adrs and length on stackCheckDrawVerb	cmp #DrawTextVerb	beq doNormText	jsr SendCStr		; Draw verb = 2: DrawCString	bra Common		; routine puts adrs and length on stackdoNormText	jsr SendText		; Draw verb = 1: normal (pascal) string			; routine puts adrs and length on stackCommon	lda 5,s		; Dup the last 3 words	pha 		; in the stack	lda 5,s	pha	lda 5,s	pha	jsr addSpeToWBuff	pushlong #EndString		; ps closeparen -- ends string	jsr AddStrToWBuff	_TextWidth		; get width of text block in scrn pixels	pla		; get it and save it	pha	pha		; pass delta_X for QD pen posn	pushword #0		; pass no delta_Y for QD pen posn	_Move		; update QD pen posn to go right of text	pla		; restore delta_X	jsr addacc	pushlong #Textmt		; call ps "merge text" routine with dX	jsr AddStrToWBuff		; and with "("string")"	pushlong #Textet		; call ps "end text" routine	jsr AddStrToWBuffExitText	lda #0ErrorExitText	cmp #1	plb	rtl		; exit Text bproc -- return back to QD*;------;Subroutines to put the length and address of different formats of strings on the stack:;SendCStr	plx	; save return address	sep #$20	longa off	ldy #0KeepLooking	lda [textPtr],y	beq TheEnd	; end of string is we hit 0	iny	bra KeepLookingTheEnd	rep #$20	longa on	lda textPtr+2	pha	lda textPtr	pha	phy	; y has the string length	phx	; restore return address	rtsSendOneChar	plx	; save return address	pushword #0	; direct page bank address	tdc	clc	adc #CharToDraw	; get address of character	pha	Pushword #1	; length	phx	; put back return address	rtsSendText	plx	; save return address	lda textPtr+2	pha	lda textPtr+0	pha	lda textLength	pha	phx	; restore return address	rts;-----------------------------------------------------------;; Subroutine to search the font directory buffer for a match of the font name.; All inputs are local parameters and returns carry clear if name is found.;DoBuffSearch	ldy NumEntriesX2	; start by matching lengths of the strings	dey	dey	; subtract 2 for indexing	lda FullFNLengloopLengCheck	cmp [LengTabPtr],y	bne KeepSearching	sty OffsetIndex	; this index will come in handy again later	tax	; save length for use later	pha	pushlong #FullFNPtr	; destination	pushlong #FullFNLeng	lda RawBuffPtr+2	; target	pha	lda [OffTabPtr],y	clc	adc RawBuffPtr	pha	phx	; the length of target	PushLong #0	; no replacement string	PushWord #0	pushlong #PadChar	; bogus pad char	_Munger	pla	; did it match?	beq FoundIt;-----------------------------------------------------------;; If we get here, it means we've had a false alarm, same length but wrong name,; so go try again.;	lda FullFNLeng	; set up the conditions again for	ldy OffsetIndex	; another time throughKeepSearching	dey	dey	bpl loopLengCheck	sec	; no match found	rtsFoundIt	clc	rts;-----------------------------------------------------------------------;; It's time to make a font! Actually we download the bitmap to the printer.; First check an internal list of fam nums of fonts already downloaded, so; we don't duplicate any efforts.; 10/18/88 Suki Lee  Rewrote portions of this routine to make it smaller; 	 and easier to follow. Eliminated a jsr to TestInFontList.;doMakeFont	lda curFontFamNum	; get the font fam num of font in use	ldy FontList	; get the list size	tyx	; put it in X also	beq AddinFontlist	; if 0, then this is our firstSearch	cmp FontList,y	; start from end of list	beq SystemF2	; if a match is found, then use it	dey	; else keep looking	dey	bne Search	; till beginning of listAddinFontlist	 	; we get here if the font is not downloaded yet	sta FontList+2,x	; store the fam num at the end of list	inx	inx	stx FontList	; update size	jsr MakeBMFont	bcc SystemF2	brl ErrorExitTextSystemF2	pushlong #UpVmStr	jsr AddStrToWBuffSendFontName	pushlong #AppleFontPrefix	jsr AddStrToWBuff	pushlong #curFontName	jsr AddStrToWBuffMakeOurOwnStyles	lda curTxStyle	and #02	beq NotItalics	pushlong #SetItalics	; set italics flag	bra SendStrNotItalics	pushlong #ClrItalics	; no italicsSendStr	jsr AddStrToWBuff	lda curTxStyle	cmp #8	; if outline or shadow, then skip	bge MakeOutlines	; bold. Mac does it this way.	and #01	; check if bold is needed	beq MakeOutlines	pushlong #MakeBoldStr	jsr AddStrToWBuff	brl AllSameMakeOutlines	lda curTxStyle	cmp #16	; shadow fonts are from 16 - 31	blt IsNotShadow	pushlong #MakeShadowStr	bra JustSendItIsNotShadow	cmp #8	; outline fonts are	from 8 - 15	blt IsNotOutline	pushlong #MakeOutlineStr	bra JustSendItIsNotOutline	pushlong #TextgfJustSendIt	jsr AddStrToWBuff	brl AllSame;-----------------------------------------------------------;; Local variables;SaveTextLength	DS.B 2	; save variablesSaveCharToDraw	DS.B 2SaveTextPtr	DS.B 4FontStlIndex	DS.B 2	; index for font style tables	EXPORT FontListFontList	DS.B 64OffsetIndex		; these are needed at different times as templimit	DS.B 2	; locations, but never togetherFNTabIndex	DS.B 2FullFNPtr	DS.B 4FullFNLeng	DS.B 2ModName	DS.B 37	; style modified font name: GS font names are 25		; chars max + worst case mod of 11 chars + leng bytepadChar	DS.B 2NewYorkStr	str 'NewYork'	; fonts that may be substitutedMonacoStr	str 'Monaco'GenevaStr	str 'Geneva'ShastonStr	str 'Shaston'	; 0CourierStr	str 'Courier'	; 1HelveticaStr	str 'Helvetica'	; 2TimesStr	str 'Times'	; 3SymbolStr	str 'Symbol'	; 4SonataStr	str 'Sonata'	; 5CartaStr	str 'Carta'	; 6ZapfDingbatsStr	str 'ZapfDingbats'	; 7AvantGardeStr	str 'AvantGarde'	; 8BookmanStr	str 'Bookman'	; 9HelveticaNwStr	str 'NHelveticaNarrow' ; 10NewCenturyStr	str 'NewCenturySchlbk' ; 11PalatinoStr	str 'Palatino'	; 12ZapfChanceryStr	str 'ZapfChancery'	; 13FNLengTable	DC.B 7	; Shaston - 0	DC.B 7	; Courier - 1	DC.B 9	; Helvetica - 2	DC.B 5	; Times - 3	DC.B 6	; Symbol - 4	DC.B 6	; Sonata - 5	DC.B 5	; Carta - 6	DC.B 12	; ZapfDingbats - 7	DC.B 10	; AvantGarde - 8	DC.B 7	; Bookman - 9	DC.B 16	; NHelveticaNarrow - 10	DC.B 16	; NewCenturySchlbk - 11	DC.B 8	; Palatino - 12	DC.B 12	; ZapfChancery - 13FNAddrTable	DC.L ShastonStr	DC.L CourierStr	DC.L HelveticaStr	DC.L TimesStr	DC.L SymbolStr	DC.L SonataStr	DC.L CartaStr	DC.L ZapfDingbatsStr	DC.L AvantGardeStr	DC.L BookmanStr	DC.L HelveticaNwStr	DC.L NewCenturyStr	DC.L PalatinoStr	DC.L ZapfChanceryStrStyleTable	DC.L HelveticaP	; Shaston is made with Helvetica	DC.L HelveticaB	DC.L HelveticaI	DC.L HelveticaBI	DC.L CourierP	DC.L CourierB	DC.L CourierI	DC.L CourierBI	DC.L HelveticaP	DC.L HelveticaB	DC.L HelveticaI	DC.L HelveticaBI	DC.L TimesP	DC.L TimesB	DC.L TimesI	DC.L TimesBI	DC.L SymbolStr	DC.L SymbolStr	DC.L SymbolStr	DC.L SymbolStr	DC.L SonataStr	DC.L SonataStr	DC.L SonataStr	DC.L SonataStr	DC.L CartaStr	DC.L CartaStr	DC.L CartaStr	DC.L CartaStr	DC.L ZapfDingbatsStr	DC.L ZapfDingbatsStr	DC.L ZapfDingbatsStr	DC.L ZapfDingbatsStr	DC.L AvantGardeP	DC.L AvantGardeB	DC.L AvantGardeI	DC.L AvantGardeBI	DC.L BookmanP	DC.L BookmanB	DC.L BookmanI	DC.L BookmanBI	DC.L HelveticaNwP	DC.L HelveticaNwB	DC.L HelveticaNwI	DC.L HelveticaNwBI	DC.L NewCenturyP	DC.L NewCenturyB	DC.L NewCenturyI	DC.L NewCenturyBI	DC.L PalatinoP	DC.L PalatinoB	DC.L PalatinoI	DC.L PalatinoBI	DC.L ZapfChancery	DC.L ZapfChancery	DC.L ZapfChancery	DC.L ZapfChanceryNoSuffix	DC.B 0Bold	str '-Bold'Italic	str '-Italic'BoldItalic	str '-BoldItalic'StyleModTable	DC.L NoSuffix	DC.L Bold	DC.L Italic	DC.L BoldItalic	ENDP******************************************************************* MakeBMFont  (new version)** parameters on stack: Long handle to the font******************************************************************	EXPORT MakeBMFontMakeBMFont	PROC	pushlong #UpVmStr	; neccessary saves and memory checking	jsr AddStrToWBuff	; in the printer;---------------------------------------------------------------------;; Send bounding box information;	lda ascent	jsr addacc	lda kernMax	jsr addacc	lda #0	ldy #FDescent	sec	sbc [fontRecPtr],y	jsr addacc	ldy #FBBDX	; fRectWidth	lda [fontRecPtr],y	jsr addacc	pushlong #bbstr	jsr AddStrToWBuff;----------------------------------------------------------------;; Create a PostScript array big enough for FirstChar to LastChar + 1; elements for the character bitmap data.;	lda LastChar	inc a	inc a	jsr AddAcc	pushlong #ChardataStr	jsr AddStrToWBuff;------------------------------------------------------------------------;; While we still have QD's zero page, set up some local variables from values; on QD's zero page;	lda firstChar	sta OurFirstChar	lda lastChar	sta OurLastChar	lda rowBytes	; width in bytes	sta RowWidth;-----------------------------------------------------------;; Move the necessary pointers to our own zero page via the stack.;	phd	; save QuickDraw's direct page	lda fontRecPtr+2	; pointer to the Mac-style part of the record	pha	lda fontRecPtr	pha	lda strikePtr+2	; pointer to the bit image	pha	lda strikePtr	pha	lda locTPtr+2	; pointer to the location table	pha	lda locTPtr	pha	lda OWTPtr+2	; pointer to the offset/ width table	pha	lda OWTPtr	pha	lda ZeroPage	tcd	; use our own zero page	pla 	; put the pointer in our own zero page	sta PtrOWTable	pla	sta PtrOWTable+2	pla	sta PtrLocTable	pla	sta PtrLocTable+2	pla	sta PtrBitImage	sta PtrWorkingBit	pla	sta PtrBitImage+2	sta PtrWorkingBit+2	pla	sta PtrMacRec	pla	sta PtrMacRec+2;--------------------------------------------------------------------;; Get memory to build a local table of the character table.;	lda #CTableSize	; 256 characters @ 6 bytes each = 1536	ldx #%1000000000011000 ; locked and dont cross bank	jsr OurGetHandle	bcc GotMemory	brl ErrorExitGotMemory	sta PtrCharTable	stx PtrCharTable+2	lda [PtrCharTable]	tax	ldy #2	lda [PtrCharTable],y	sta PtrCharTable+2	stx PtrCharTable;--------------------------------------------------------------------;; Calculate the necessary values for Character Table data in the; form of : rowbytes Yoffset Xoffset width imagewidth imageheight;;    rowbytes - of the character image;    Yoffset - # of	pixels from last row of bit image to bottom;              of character rectangle;    Xoffset - # of	pixels from the left edge of the bit image to;              the left edge of the char rectangle;              is kept in high byte of OwTable value;    width - # of pixels from this characters's origin to the next's;            is kept in low byte of OwTable;    imagewidth - width of character image;               = next char's offset - this char's offset in LocTable;    imageheight - height of character image;                  # of non zero rows in character image; Note: Image height is used instead of	font height to save	space in; the font cache of	the LaserWriter.;	pushlong #OpenHex	jsr AddStrToWBuff;---------------------------------------------------------------------;; Set up table index and locOffset as the pointer to the beginning of this; character's 6 byte entry;	stz TableIndex	stz locOffset;----------------------------------------------------------------------;; The loop to stuff	the table;LoopCharTable	lda TableIndex	cmp OurFirstChar	bge @1	brl CharNotDefined	; Char IDs less than FirstChar or@1	lda OurLastChar	; greater than LastChar+1 are not	inc a	; defined	cmp TableIndex	bge @2	brl CharNotDefined;----------------------------------------------------------------------;; Calulate CharIndex from TableIndex; TableIndex ranges	from 0 to 256, use for indexing CharTable; CharIndex ranges from (TableIndex-FirstChar) to (TableIndex-(LastChar+1)),; use for indexing the OWTable and locTable;@2	lda TableIndex	sec	sbc OurFirstChar	; this index will be used for	asl a	; locTable and OWTable, multiply	sta CharIndex	; by two for indexing bytes;----------------------------------------------------------------------;; Calculate imagewidth;	tay	iny	; get next char's offset	iny	lda [PtrLocTable],y	; pointer to LocTable	sec	dey	; set index back to	this char	dey	sbc [PtrLocTable],y	; subtract to get the imagewidth	sta tempWidth	; save for use later	tax	; temporarily move the value to x	lda #oImageWidth	; add the offset to	the offset of	clc	; this character's chunk	adc locOffset	tay	; use it as an index	txa	; get the real value back	sep #$0020	longa off	sta [PtrCharTable],y ; store in the proper place	longa on	rep #$0020;-------------------------------------------------------------------;; Calculate rowbytes using imagewidth in accumulator;   divide imagewidth by the number of pixels in a word (16);   if no remainder, then everything fit in the number of words;     reflected in the quotient;   if there is a remainder, then increase the quotient by 1;   finally, multiply quotient by 2 to get # of bytes;	pha	; space for remainder	pha	; space for quotient	pha	; numerator, which is imagewidth	lda #16	; 2 bytes, keep on word boundary	pha	; denominator	_UDivide	plx	; get quotient	pla	; check remainder	beq AsIs	; if none then quotient is rowwords	inx	; otherwise bump by	oneAsIs	txa	; move rowWords	asl a	; translate into # of bytes	ldy locOffset	; rowBytes is offset 0	sep #$0020	longa off	sta [PtrCharTable],y	longa on	rep #$0020;------------------------------------------------------------------------;; Figure out YOffset; First we need to figure out the top and bottom of the smallest; rectangle that will enclose all of the character's image. In other; words, the # of all zero rows at top and bottom of the image. Yoffset; is the same as the value for bottom.;	stz cTop	stz cBottom	cmp #0	; was rowbyte 0?	bne MovingAlong	; no, keep going	brl BotmOfImage	; otherwise, skip the rest of this sectionMovingAlong	ldy CharIndex	lda [PtrLocTable],y	pha	; space for remainder	pha	; space for quotient	pha	lda #16	pha	_UDivide	pla	; get quotient	asl a	sta charStart	; offset from start of strike, save for now	clc	adc PtrBitImage	sta PtrWorkingBit	lda PtrBitImage+2	adc #0	sta PtrWorkingBit+2;-----------------------------------------------------------;; The remainder from the division is the bit offset from the nearest word; boundary. Use this value to index the mask table to get rid of bits on; left that don't belong;	pla	; now the remainder	sta remain	asl a	; double to be used as word index	tax	; into left mask table	lda LW_LeftMask,x	sta mask	stz imageOffset;-----------------------------------------------------------;; Find out if the right side needs masking also. Determine how many of the; character's bits are in this word and how many (if any) are in the next; word. There may also be bits that don't belong on the right if the; character width is small.;	lda #16	; 16 (bits in a word) - remainder	sec	; will tell how many bits is used	sbc remain	; up in this word	sta leftOver	lda tempWidth	sec	sbc leftOver	; see how much is left in next word(s)	sta leftOver	; save for now	bpl loopTop	; the bits either fits perfectly, or		; overflows into the next word(s) so		; no right mask is needed	clc	; some unwanted bits on right side	adc #16	; get an index for a right mask	asl a	tax	; to get rid of it	lda LW_RightMask,x	and mask	sta maskLoopTop		; mask off the unwanted stuff	lda [PtrWorkingBit]	xba	and mask	beq @4	brl TopOfImage@4	stz leftOver2;-----------------------------------------------------------;; Now for the next word: if no leftover, then life is simpler. Otherwise,; need to find out if everything that's left fits into the next word, If; it doesn't then life is way more complicated.;; All the bits of the character need to be left justified before sending.; In the simple case where all the bits are in one word, we just shift; left. But if the bits span two words, then we need to shift left for; second word and rotate left for first word. This procdure needs to be; done twice if the bits span three words.;	lda leftOver	; are we done yet?	bpl @1	; if > 0, then do some more work@2	brl ThisRowDone	; if <= 0, then done@1	beq @2	ldy #2	; if we're here, we