aracter is not defined, we can send	$FF as the rowbyte value and; 0s for the rest since the BuildChar procedure ignores these values; if rowbytes = $FF;CharNotDefined	ldy locOffset	; set rowbytes to FF to denote an	lda #$00FF	; undefined character	sta [PtrCharTable],y	iny	iny	lda #$0000	; 0's for the next 4 bytes	sta [PtrCharTable],y	iny	iny	sta [PtrCharTable],y	brl NextChar;----------------------------------------------------------------------;; Now that we've stuffed the table, it's time to send it;SendCharTable	ldy #0	ldx #0LoopCTable	lda [PtrCharTable],y	phy	phx	jsr AddHexWord	lda iPrErr	beq @3	pla	; get rid of stuff on stack	pla	brl ErrorExit1@3	plx	inx	cpx #3	; done 3 words yet	bne @1	; nope	pushlong #Return	; add a carriage return	jsr AddStrToWBuff	ldx #0	; start count all over again@1	ply	iny	iny	cpy #CTableSize	; to the end yet?	blt LoopCTable	pushlong #closeHex	jsr AddStrToWBuff	pushlong #CharTableStr	jsr AddStrToWBuff****************************************************************** to get bit image of a character:;-----------------------------------------------------------;; TableIndex was being incremented during the stuffing of the CharTable; it should be equal to 256 at this time.;	dec TableIndex	; start from the back at 255	lda #255*6	sta locOffset	; reset the local offset variable	lda PtrBitImage+2	sta PtrWorkingBit+2	; reset the bit image pointer bank address;----------------------------------------------------------------;; The big loop: send the bits for each character's image;LoopChars	ldy locOffset	lda [PtrCharTable],y ; get rowbyte from CharTable	and #$00FF	; in low byte	bne @1	; rowbyte of 0 means no bits	brl GoToNextChar@1	cmp #$00FF	; rowbyte of $FF indicates missing char	bne @2	brl GoToNextChar	; no bits to be sent@2	lda TableIndex	cmp OurFirstChar	bge @3	brl CharNotDefined	; Char IDs less than FirstChar or@3	lda OurLastChar	; greater than L