n three words.;	lda leftOver	bpl @1@2	brl WeBeDone@1	beq @2	ldy #2	; if we're here, we should be	sty ImageOffset	; on word 2	pha	; remainder	pha	; quotient	pha	; dividend already in A	lda #16	pha	_UDivide	pla	; get quotient	bne @3	pla	; ignore the remainder in this case	lda leftOver	; less than 16	asl a	tax	; save this for next word as index	lda LW_RightMask,x	; Note: if leftOver is 16, it'll grab	sta mask1	; the first entry of LW_LeftMask (FFFF)	lda #1	sta wholeWords	; this is to fool the loop count check	bra OneMoreWord@3	sta wholeWords	; save for later use	pla	; get remainder	sta leftOver2	lda #$FFFF	sta mask1	; use the whole wordOneMoreWord	ldy ImageOffset	lda [PtrWorkingBit],y	xba	and mask1	ldx remain	beq NoShiftloop1	asl a	rol scratch	dex	bne loop1NoShift	sta scratch1	lda scratch	xba	jsr AddHexWord	lda iPrErr	beq @1	brl ErrorExit1@1	stz scratch	; start it off clean	lda #16	; figure out how many bits need	sec	; to be put into scratch for	sbc remain	; more merging	tax	lda scratch1loopx	asl a	rol scratch	dex	bne loopx	lda imageOffset	inc a	inc a	sta imageOffset	lda wholeWords	dec a	sta wholeWords	bne oneMoreWord	lda leftOver2	; nothing in third word	beq ThatsAll	asl a	tax	; use leftover value for getting	lda LW_RightMask,x	; the right mask	sta mask2	ldy ImageOffset	; get the next next word	lda [PtrWorkingBit],y	xba	and mask2	ldx remain	; merge whatever is left	beq ShiftNotNeededloop4	asl a	rol scratch	dex	bne loop4ShiftNotNeeded	sta scratch1	lda scratch	xba	jsr AddHexWord	lda iPrErr	beq @1	brl ErrorExit1@1	lda leftOver2	sec	sbc remain	bpl @2	bra NextRow@2	beq NextRow	lda scratch1	bra SendItThatsAll	lda scratch1	; something good left?	bne SendIt	; yeah, send it off	ldx tempWidth	; only 0's left	cpx #17	; check if wide word	blt NextRow	; if not, skip it	bra SendIt	; already have 0's shifted inWeBeDone	lda scratch	ldx remain	beq SendIt	; bi