C.W $FFFE	; 15LW_LeftMask	DC.W $FFFF	; 0	DC.W $7FFF	; 1	DC.W $3FFF	; 2	DC.W $1FFF	; 3	DC.W $0FFF	; 4	DC.W $07FF	; 5	DC.W $03FF	; 6	DC.W $01FF	; 7	DC.W $00FF	; 8	DC.W $007F	; 9	DC.W $003F	; 10	DC.W $001F	; 11	DC.W $000F	; 12	DC.W $0007	; 13	DC.W $0003	; 14	DC.W $0001	; 15;---------------------------------------------------------------------;; Local variables, many used as local copies of fields from	the font; record to save indexing.;LocOffset	DS.B 2	; points at the beginning of the char's 6 bytes		; entry in the CharTableTableIndex	DS.B 2	; index to the local character tableCharIndex	DS.B 2	; Char's ASCII code used as indexOurFirstChar	DS.B 2	; local copy of firstCharOurLastChar	DS.B 2	; local copy of lastCharrowWidth	DS.B 2	; width of font strike in bytescTop	DS.B 2	; # of nonzero rows	on top of imagecBottom	DS.B 2	; # of nonzero rows	on bottom of imagecharStart	DS.B 2	; starting location of char's imagecharTop	DS.B 2	; loc of first byte of image for each rowcharBottom	DS.B 2	; starting loc of last row of imagetempWidth	DS.B 2	; temp variable for	imageWidthTopTable	DS.B 512	; table of top valuesremain	DS.B 2	; bit offset within a wordscratch	DS.B 2	; temp bufferscratch1	DS.B 2	; dittomask	DS.B 2	; masks for getting rid of unwanted bitsmask1	DS.B 2mask2	DS.B 2leftOver	DS.B 2	; overflow into next wordleftOver2	DS.B 2	; overflow into next next wordimageOffset	DS.B 2	; offset of bytes within the imagewholeWords	DS.B 2	; number of whole words that the image spans	ENDP;                copy    Pixel*****************************************************************              			   ** Pixel           			   **              			   **              			   ** Revised to use new PostScript - GSPrep      	   **              			   *****************************************************************	EXPORT pixelpixel	PROC	jsr testSave	beq DoPixel	lda >DefaultProcs+$21	pha	phb	pla	lda >DefaultProcs+$20	pha	rtlDoPixel	phb	phk	plb* we need to send xscale,yscale (72* final size)* then Xloc Yloc are the destpoint* rowbytes must be even* xwidth and ywidth	are the actual size	in points*	lda iPrErr	beq Continueexitnow	brl ExitPixelContinue;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we wouldn't try not to send any unnecessary PostScript; code to LaserWriter;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow	ldy #opnVis	lda [Qdport],y	bmi exitnow;-----------------------------------------------------------------;; Save stuff that we need from QD's zero page in local variables.; QD's zero page gets changed each time we reset the current port; during status update. We will restore	the pointers each time they; are used, and will use the local copy	for other variables.;	lda QDPort	; port pointer	sta SaveQDPort	lda Qdport+2	sta SaveQDPort+2	ldx #06	; dest rectLoopSaveDest	lda DestRect,x	sta SaveDestRect,x	dex	dex	bpl LoopSaveDest	ldx #22	; SrcSCB, SrcPixelMapRef, SrcWidth,LoopSave	lda SrcSCB,x	; SrcBounds and SrcRect are all	sta SaveSCB,x	; contiguous on zero page	dex	dex	bpl LoopSave;-----------------------------------------------------------------------;; We will need to define a string to be	used to read hex data from the; pixel map, its size is:  (sample/line) * (bits/sample) / 8 (bits/byte); What we need to know is the ideal # of characters we need to put all; the bits on one line into the string. (1 char = 1 byte);    for 640 mode: bits/sample is 2 -->	denominator = 4;    for 320 mode: bits/sample is 4 -->	denominator = 2; Problems will arise if the pixel map has a sample/line value that is; not divisible by the denominator, so we safegaurd against	this case; by increasing the	string size:;     640 mode: add	3, and with $FFFC before dividing;     320 mode: add	1, and with $FFFE before dividing;	lda SaveRect+6	; find out the width of the pixel	sec	; map (samples/line)	sbc SaveRect+2	sta xwidth	tax	; temporary stashing	lda SaveSCB	; check mode	and #$0080	beq IsMode320	txa	; get it back	clc	adc #0003	and #$FFFC	lsr a	; divide by 4, by two here	bra GoOnIsMode320	txa	inc a	and #$FFFEGoOn	lsr a	; divide by 2	sta newWidth	; use to define the	string size	lda SaveRect+4	sec	sbc SaveRect	sta ywidth	; height of pixel map	jsr checkPort	lda PixelInstalled	bne NoInstall	dec PixelInstalled;               pushlong #BuStr;               jsr	AddStrToWBuff	jsr colorNoInstall	pushlong #saveStr	jsr AddStrToWBuff	pushlong #OrigScreen	jsr AddStrToWBuff;-----------------------------------------------------------------------;; Define the PostScript string for reading hex data, this string is used; by the procedure called by the image operator;	pushlong #PicStr	jsr AddStrToWBuff	lda newWidth	jsr AddAcc	pushlong #DefPicStr	jsr AddStrToWBuff;               pushlong #BNstr;               jsr	AddStrToWBuff;	jsr setBlack	pushlong #Levelstr	jsr AddStrToWBuff	lda SaveDestRect+2	pha	lda SaveDestRect	pha	jsr translate	lda SaveDestRect+6	; find out the width of the rectangle	sec	; to scale image to	sbc SaveDestRect+2	pha	lda SaveDestRect+4	; find out the height of the rectangle	sec	; to scale image to	sbc SaveDestRect	pha	jsr scale	lda xwidth	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	lda ywidth	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	lda SaveSCB	; check mode for sending value	and #$0080	; for bits/sample	beq mod320	lda #2	; 2 bits/sample for	640 mode	bra suitemod320	lda #4	; 4 bits/sample for	320 modesuite	jsr addacc	pushlong #openbracket	jsr AddStrToWBuff	lda xwidth	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	lda #0	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	lda #0	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	lda ywidth	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	lda #0	jsr addacc	pushlong #SpaceChar	jsr AddStrToWBuff	lda #0	jsr addacc	pushlong #closebracket	jsr AddStrToWBuff	pushlong #procimage	jsr AddStrToWBuff;----------------------------------------------------;; Now we adjust SrcPixelMapRef to point	to the first; byte in the pixel	map.;	jsr RestorePtr	; first, restore the original;       ; SrcPixelMapRef	pea 0	; result of multiply	pea 0	lda SaveRect	sec	sbc SaveBounds	beq StartWith1stLine	pha	PushWord SaveWidth	_MultiplyStartWith1stLine	lda SaveRect+2	sec	sbc SaveBounds+2	lsr a	bit SaveSCB-1	bpl Not640	lsr aNot640	clc	adc 1,s	sta 1,s	bcc NoCarry	lda 3,s	inc a	sta 3,sNoCarry	pla	clc	adc SrcPixelMapRef	sta LocalPixelMapRef	pla	adc SrcPixelMapRef+2	sta LocalPixelMapRef+2* ok now we add the	bits...	lda #0moreline	pha	tay	lda LocalPixelMapRef	sta SrcPixelMapRef	lda LocalPixelMapRef+2	sta SrcPixelMapRef+2	lda [SrcPixelMapRef],y	jsr AddHexByte	pla	inc a	cmp newWidth	blt moreline* endLine	pushlong #return	jsr AddStrToWBuff	lda LocalPixelmapRef	clc	adc SaveWidth	sta LocalPixelmapRef	lda LocalPixelMapRef+2	adc #0	sta LocalPixelMapRef+2	lda #0	dec yWidth	bne moreline	pushlong #restoreStr	jsr AddStrToWBuff;-------------------------------------------------------------------;; Restore original stuff back onto QD zero page;	lda SaveQDPort	; port pointer	sta QDPort	lda SaveQDport+2	sta QDPort+2	ldx #06	; dest rectLoopResDest	lda SaveDestRect,x	sta DestRect,x	dex	dex	bpl LoopResDest	ldx #22	; SrcSCB, SrcPixelMapRef, SrcWidth,LoopRestore	lda SaveSCB,x	; SrcBounds and SrcRect are all	sta SrcSCB,x	; contiguous on zero page	dex	dex	bpl LoopRestoreExitpixel	lda #0	clc	plb	rtlnewWidth	DS.B 2xwidth	DS.B 2ywidth	DS.B 2;Local storage for original zero page valuesSaveQDport	DS.B 4	; QDPortSaveDestRect	DS.B 8	; DestRectSaveSCB	DS.B 2	; SrcSCB	EXPORT SavePtrSavePtr	DS.B 4	; SrcPixelMapRefSaveWidth	DS.B 2	; SrcWidthSaveBounds	DS.B 8	; SrcBoundsSaveRect	DS.B 8	; SrcRectLocalPixelMapRef	DS.B 4	; recalculated SrcPixleMapRef	ENDP******************************************************************* RestorePtr** Restores SrcPixelMapRef. Called before SrcPixelMapRef is used* for indirect indexed addressing each time.******************************************************************	EXPORT RestorePtrRestorePtr	PROC	lda saveptr	sta SrcPixelMapRef	lda saveptr+2	sta SrcPixelMapRef+2	rts	ENDP;                copy    Comment****************************************************************** Comment: picture comments** Current Rev: Jan 08, 1988*****************************************************************	EXPORT CommentComment	PROC	phb	phk	plb	lda iPrErr	beq Continueexitnow	brl ExitCommentContinue;------------------------------------------------------------------------;; It is necessary to check page range here, since each page's QuickDraw; calls are processed regardless of the	range of pages to be printed. For; efficiency sake, we try not to send any unnecessary PostScript code to; the LaserWriter.;	lda iPageNum	cmp hPrint+prJob+iFstPage	blt ExitNow	dec a	cmp hPrint+prJob+iLstPage	bge ExitNow	ldy #opnVis	lda [Qdport],y	bmi exitnow;----------------------------------------------------------------------;; Saves the important stuff in local variables from QuickDraw's zero; page.;	lda TheKind	sta SaveKind	lda TheSize	sta SaveSize	lda TheHandle	; use temp locations on QD's	sta ScratchPtr1	; zero page for dereferencing	lda TheHandle+2	sta ScratchPtr1+2	ldy #2	; dereference and store in local	lda [ScratchPtr1],y	; pointer	sta PSptr+2	lda [ScratchPtr1]	sta PSptr;---------------------------------------------------------------------;; Determine what kind of comment this is;	lda SaveKind	cmp #PostScriptBegin	blt CleanExit	; we currently do not recognize anything	cmp #PostScriptText+1 ; other than the five comments used	bge CleanExit	; for encapsulated PostScript	sec	sbc #PostScriptBegin ; get an index beginning at zero	asl a	tax	jmp (CommentTable,x)CommentTable	DC.W PSBegin	; 190	DC.W PSEnd	; 191	DC.W PSHandle	; 192	DC.W PSFile	; 193	DC.W PSText	; 194CleanExit	lda #0ExitComment	cmp #1	plb	rtl;---------------------------------------------------------------------;; Comments:  0  -- none;            1  -- PostScript text;           -1  -- other comments;;---------------------------------------------------------------------;; Comment 190 : PostScript Begin;; Switch from QuickDraw mode to PostScript mode;PSBegin	lda Comments	; cannot begin unless none were in	bne CleanExit	; effect to start with	dec Comments	; signify PostScript mode	pushlong #PSBeginStr	jsr AddStrToWBuff	bra CleanExit;---------------------------------------------------------------------;; Comment 191 : PostScript End;; Switch from PostScript mode to QuickDraw mode;PSEnd	lda Comments	; don't end unless it's been begun	beq CleanExit	stz Comments	; put things back to QD mode	pushlong #PSEndStr	jsr AddStrToWBuff	bra CleanExit;---------------------------------------------------------------------;; Comment 192 : PostScript Handle;; PostScript text is pointed to by handle;PSHandle	lda Comments	; don't do anything if begin	beq CleanExit	; hasn't been called	lda PSptr+2	; pointer to the text	pha	lda PSptr	pha	lda SaveSize	; length of text	pha	jsr AddTextToWBuff	bra CleanExit;---------------------------------------------------------------------;; Comment 193 : PostScript File;; PostScript text is contained in file whose name is pointed to by; handle;PSFile	lda Comments	; don't do anything if begin	beq CleanExit	; hasn't been called	jsr WriteLaser	; send the stuff in	write buffer since		; downloadfile will kill it	lda PSptr+2	pha	lda PSptr	pha	pushlong #OpenFileName+2	PushWord #0	lda SaveSize	pha	_BlockMove	lda SaveSize	; stick the size in	the beginning	sta OpenFileName	; of the string	jsr downloadfile	brl ExitComment	; A should have either 0 or the error;---------------------------------------------------------------------;; Comment 194 : PostScript Text;; QuickDraw text is	actual PostScript;PSText	lda Comments	; don't do anything if begin	bpl CleanExit	; hasn't been called	lda #1	; let the text routine know it should	sta Comments	; send the text as PostScript	brl CleanExitSaveKind	DS.B 2SaveSize	DS.B 2PSptr	DS.B 4	ENDP;                Copy    utilities	EXPORT utilitiesutilities	PROC	EXPORT TestSaveTestSave	ldy #oRgnSave	lda [Qdport],y	iny	iny	ora [Qdport],y	iny	iny	ora [Qdport],y	iny	iny	ora [Qdport],y	rts	EXPORT scalescale	lda 5,s	jsr addacc	pushlong #SpaceChar	; force a space between the two	jsr AddStrToWBuff	; scale factors	lda 3,s	jsr addacc	pushlong #scalestr	jsr AddStrToWBuff	plx	pla	pla	phx	rts	EXPORT translatetranslate	lda 5,s	jsr addacc	pushlong #SpaceChar	; force a space between the two	jsr AddStrToWBuff	; translation factors	lda 3,s	jsr addacc	pushlong #translatestr	jsr AddStrToWBuff	plx	pla	pla	phx	rts* we Have a ptr to a String255 on the stack and we want to add it* to the write buffer	EXPORT AddTextToWBuffAddTextToWBuff	lda 5,s	sec	sbc #1	sta QD_Temp1	lda 7,s	sbc #0	sta QD_Temp1+2	lda 3,s	jsr Common	bcc doneText	jsr WriteLaser	bcc AddTextToWBuff	lda iPrErr	cmp #iPrAbort	beq DoneText	lda #PAPReadWriteErr	sta iPrErrdoneText	ply	; get return address off stack	pla	; get rid of parameters passed	pla	pla	phy	; put return address back on	rts;--------------------------------------------------------------------;; Appends the incoming string into the write buffer if there is room.; If the existing length plus the new string length is greater than the; flow quantum, 512 bytes, then issue a PAPWrite to free up the buffer,; and then put string in.;	EXPORT AddStrToWBuffAddStrToWBuff	lda 3,s	; get pointer off stack	sta QD_Temp1+0	; and put into zero	page	lda 5,s	sta QD_Temp1+2*** added 18-Feb-93 DAL -- if pointer is NIL, don't append (PMGetUserName returns NIL on direct-connect)	ora 3,s	beq DoneStr*** end 18-Feb-93	lda [QD_Temp1]	; get the first word	and #$00FF	; get the length in	the low byte	beq DoneStr	; if length is zero then do nothing	jsr common	; go to common code	to check for space	bcc donestr	; carry clear, string is in buffer	jsr WriteLaser	; else issue a write	bcc AddStrToWBuff	lda iPrErr	cmp #iPrAbort	beq DoneStr	lda #PAPReadWriteErr	sta iPrErrDoneStr	ply	; temporarily take return addr off	pla	; get rid of ptr which was an input	pla	phy	; put back the return address	rts	; and splitCommon	tay	; store in Y for later indexing use	clc	; add new string length to the	adc WriteLength	; current buffer length	cmp #ATFlowQuantum	; is it larger than	512 (flow quantum)	blt smallEnough	; nope	sec	; yes, set carry, buffer not big enough	rts	; and returnSmallEnough	sta WriteLength	; update buffer length	dec a	; minus 1	tax	; put into X for indexing	sep #$0020	longa offtransloop	lda [QD_Temp1],y	; move the string elements one at	sta WriteBuffer,x	; a time to the buffer	dex	dey	bne transloop	longa on	rep #$0020	clc	; clear carry, buffer able to hold	rts	; the entire string	EXPORT AddHexWordAddHexWord	pha	jsr addHexByte	pla	ldx iPrErr	bne Error	xba	jsr addHexByteError	rts	EXPORT AddHexByteAddHexByte	pha	lsr a	lsr a	lsr a	lsr a	jsr ConvToASCII	sta Hexb+1	pla	jsr ConvToASCII	sta Hexb+2	pushlong #Hexb	jsr AddStrToWBuff	rts	EXPORT ConvToASCIIConvToASCII	and #$000F	clc	adc #'0'	cmp #'9'+1	blt g1	clc	adc #7g1	rtshexb	DC.B 2	DS.B 3	EXPORT addSpeToWBuffaddSpeToWBuff	stz LocPosLoopSpe	lda 5,s	sta QD_Temp1	lda 7,s	sta QD_Temp1+2	lda 3,s	cmp LocPos	beq finspe	ldy LocPos	lda [QD_Temp1],y	and #$00FF	cmp #'\'	beq spe	cmp #'('	beq spe	cmp #')'	beq spe	jsr addOneCar	inc LocPos	bra LoopSpespe	pha	lda #'\'	jsr addoneCar	pla	jsr addoneCar	inc LocPos	bra LoopSpefinspe	ply	pla	pla	pla	phy	rtsLocPos	DS.B 2addoneCar	pha	; put character on stack for later	lda WriteLength	cmp #511	; buffer full?	blt easy	; nope	jsr WriteLaser	; yep, sent it	bcc easy	lda iPrErr	cmp #iPrAbort	beq GetOut	lda #PAPReadWriteErr	sta iPrErrGetOut	plx	; get the character	off the stack	bra Exiteasy	ldx WriteLength	pla	; get character off	stack	sta Writebuffer,x	; store into buffer	inc WriteLength	; bump lengthExit	rts	ENDP*****************************************************************	EXPORT addCoordinateaddCoordinate	PROC	ply	; remove return address for now	pla	sta penPos	; get pointer off stack	pla	sta penpos+2	phy	; put return address back	lda PenPos	jsr AddAcc	lda PenPos+2	jsr AddAcc	rts	ENDP*****************************************************************	EXPORT AddAccAddAcc	PROC	ldy #0	and #$FFFF	bpl plus	deyplus	phy	pha	pushlong #numstr	pushWord #5	; changed from 4 to	5 by Suki	Pushword #$FFFF	; 5/5/87 for safeguard reasons	_Long2dec	pushlong #SpaceChar	; separate each entry with a space	jsr AddStrToWBuff	pushlong #numstr	pushWord #5	; also changed on 5/5/87	jsr AddTextToWBuff	rts	ENDP******************************************************************** OurGetHandle** Gets a handle to memory of size passed in a-reg with* attributes passed	in x-register.** Handle is returned in A & X registers	unless there is a* memory manager error where error returns in a-reg.*******************************************************************	EXPORT OurGetHandleOurGetHandle	PROC	pha	pha	pea 0	pha	PushWord LW_UserID	; your ID	phx	pha	pha	_NewHandle 	; result on the stack	bcs AnError	pla	plx	rtsAnError	plx	plx	rts	ENDP******************************************************************** CursorStuff** Has tool calls for wait and setcursor.*******************************************************************	EXPORT CursorStuffCursorStuff	PROC	EXPORT WaitCursorWaitCursor;------------------------------------------------------------;; Get the current cursor record's address and turn on the watch cursor.;	pha	pha	; space for the address	_GetCursorAdr	pla	sta CursorAd	pla	sta CursorAd+2	_WaitCursor	rts	EXPORT RestoreCursorRestoreCursor	PushLong CursorAd	_SetCursor	rts	ENDP	END